'use client';
// THE STATE PILL — spec 398 §5.1: the one way a run, task, endeavor or trigger state is shown. Renders the
// projected word (`runStateLabel`), coloured by tone, with the record's native term as the tooltip when the
// caller has one worth showing ("Planning" under `queued`). `data-state` carries the projected word for tests
// and for the census gate.
import type { CSSProperties } from 'react';
import { runStateLabel, stateTone, type ProjectedRunStateV1 } from '../../home/run-state';

const TONE: Record<ReturnType<typeof stateTone>, { bg: string; fg: string; border: string }> = {
  idle: { bg: 'var(--color-surface-sunken, #f4f4f2)', fg: 'var(--color-text-muted, #6b7280)', border: 'var(--color-border)' },
  active: { bg: 'var(--color-sage-50, #f0f7f2)', fg: 'var(--color-sage-700, #2f6846)', border: 'var(--color-sage-500, #5f9b76)' },
  attention: { bg: 'var(--color-amber-50, #fffbeb)', fg: 'var(--color-amber-700, #b45309)', border: 'var(--color-amber-400, #fbbf24)' },
  done: { bg: 'var(--color-sage-100, #dfeee4)', fg: 'var(--color-sage-700, #2f6846)', border: 'var(--color-sage-500, #5f9b76)' },
  bad: { bg: 'var(--color-red-50, #fef2f2)', fg: 'var(--color-red-700, #b91c1c)', border: 'var(--color-red-300, #fca5a5)' },
  // unknown — reconciling: neither running's green nor failed's red, on purpose (T10)
  uncertain: { bg: 'var(--color-surface-sunken, #f4f4f2)', fg: 'var(--color-text, #111827)', border: 'var(--color-amber-400, #fbbf24)' },
};

export function statePillStyle(p: ProjectedRunStateV1, extra?: CSSProperties): CSSProperties {
  const t = TONE[stateTone(p)];
  return {
    display: 'inline-block', padding: '1px 8px', borderRadius: 999, fontSize: '11.5px', fontWeight: 600, lineHeight: 1.5,
    whiteSpace: 'nowrap', background: t.bg, color: t.fg, border: `1px solid ${t.border}`, ...(extra ?? {}),
  };
}

const V2_TONE: Record<ReturnType<typeof stateTone>, string> = { idle: 'neutral', active: 'info', attention: 'warn', done: 'ok', bad: 'danger', uncertain: 'warn' };

export function StatePill({ state, native, style, compact }: { state: ProjectedRunStateV1 & { unknownNative?: string }; native?: string; style?: CSSProperties; compact?: boolean }) {
  const label = runStateLabel(state);
  const tip = state.unknownNative ? `unmapped state: ${state.unknownNative}` : native && native !== label ? native : undefined;
  const tone = stateTone(state);
  // Design system v2: the pill IS the status badge — a dot and a soft tint, one vocabulary on every surface; a
  // running state pulses. `statePillStyle` stays for legacy inline callers.
  return (
    <span
      className={`state-pill ui-status ui-status--${V2_TONE[tone]}${tone === 'active' ? ' ui-status--live' : ''}`}
      data-state={state.state}
      data-effect-uncertain={state.effectUncertain ? 'true' : undefined}
      title={tip}
      style={{ ...(compact ? { fontSize: '11px' } : {}), ...(style ?? {}) }}
    >
      {label}
    </span>
  );
}

// ONE STATE VOCABULARY, EVERYWHERE — spec 398 §5.1 (APUX-024). A Home surface never renders a record's NATIVE state
// (a run's `outcome`, a task's `input-required`, an endeavor's `adopted`, a trigger's `answered`): it renders the
// projection `@agenticprimitives/harness/run-state` makes — the same pure table the runtime's `/harness/runs` and
// the Home MCP project from — so "waiting for a signature" is one phrase wherever a person meets it. What this
// module adds is only the Home's side: the tone a pill takes, and the native word kept as a TOOLTIP (the domain's
// own term — "Planning", "Requested" — is still worth seeing; it is just not the state).
//
// `effect-uncertain` is orthogonal and never collapsed into `failed` (T10): the pill says "unknown — reconciling"
// and no retry is offered on it. Nothing here is authority: a state is a word for a person; no gate reads it.
import { projectRunState, runStateLabel, RUN_STATES, type AwaitingKind, type ProjectedRunStateV1, type RunStateSource, type RunStateV1 } from '@agenticprimitives/harness/run-state';

export { projectRunState, runStateLabel, RUN_STATES };
export type { AwaitingKind, ProjectedRunStateV1, RunStateSource, RunStateV1 };

/** The tone a pill takes — five, not eleven: a person reads the colour before the word. */
export type StateTone = 'idle' | 'active' | 'attention' | 'done' | 'bad';

export const STATE_TONE: Record<RunStateV1, StateTone> = {
  drafted: 'idle',
  queued: 'idle',
  running: 'active',
  recovering: 'active',
  'awaiting-input': 'attention',
  'awaiting-approval': 'attention',
  blocked: 'attention',
  completed: 'done',
  failed: 'bad',
  canceled: 'idle',
  expired: 'idle',
};

/** `effect-uncertain` is its own tone: neither running nor failed, and never the colour of either. */
export function stateTone(p: ProjectedRunStateV1): StateTone | 'uncertain' {
  return p.effectUncertain ? 'uncertain' : STATE_TONE[p.state];
}

/** Project, refusing nothing at render time: a word the table does not know renders as `failed` WITH the native
 *  word in the tooltip and a console error — a screen must not blank on one unknown row, and the unknown must
 *  not pass as a plausible state either. */
export function stateOf(source: RunStateSource, opts: { effectUncertain?: boolean } = {}): ProjectedRunStateV1 & { unknownNative?: string } {
  try {
    return projectRunState(source, opts);
  } catch (e) {
    const native = nativeWord(source);
    console.error(`[run-state] ${e instanceof Error ? e.message : String(e)} — rendered as failed`);
    return { state: 'failed', effectUncertain: false, unknownNative: native };
  }
}

/** The record's own word, for the tooltip. */
export function nativeWord(source: RunStateSource): string {
  switch (source.kind) {
    case 'run': return source.canceled ? 'canceled' : source.expired ? 'expired' : source.awaiting ? `${source.outcome} (${source.awaiting})` : source.outcome;
    case 'suspended': return source.expired ? 'expired' : `suspended${source.awaiting ? ` (${source.awaiting})` : ''}`;
    case 'task': return source.state;
    case 'recovering': return 'recovering';
    case 'trigger': return source.paused ? 'paused' : source.lastOutcome;
    case 'endeavor': return source.lifecycle;
    case 'step': return source.status;
  }
}

'use client';
// THE BASIS LINE — spec 398 §4.4: "acting as ‹you› · in ‹Missio Nexus› · basis: stewardship". On every mutation screen
// and review card, the same two facts and the same words the switcher's caption uses (`actingBasis`). Optional third
// clause: what THIS act needs (describeRequirement's words) — the requirement, never a role name.
import { usePathname } from 'next/navigation';
import { useMemo } from 'react';
import { useSession } from '../../context/session';
import { useManagedAgents } from './ManagedAgents';
import { agentClassOf } from '../../lib/agent-class';
import { nameLabel } from '../../lib/domain';
import { parseWorkspacePath, type WorkspaceScope } from '../../lib/workspace';
import { actingBasis, type ActingBasis } from '../../lib/acting-basis';
import { BuildingIcon, LandmarkIcon, UserIcon } from '../shared/Icons';

const short = (a: string) => `${a.slice(0, 6)}…${a.slice(-4)}`;
const Icon = ({ kind }: { kind: ActingBasis['in']['kind'] }) => (kind === 'person' ? <UserIcon size={12} /> : kind === 'org' ? <BuildingIcon size={12} /> : <LandmarkIcon size={12} />);

/** Compute the basis for the ACTIVE workspace (or a given scope) from what the Home lists. */
export function useActingBasis(scope?: WorkspaceScope, delegationInHand?: boolean): ActingBasis | null {
  const { session, agentAddress, agentName, personName } = useSession();
  const pathname = usePathname();
  const { agents } = useManagedAgents(session?.token ?? null, 'any');
  return useMemo(() => {
    if (!agentAddress) return null;
    const active = scope ?? parseWorkspacePath(pathname ?? '/');
    const self = { address: agentAddress, ...(personName ? { name: personName } : agentName ? { name: nameLabel(agentName) } : {}) };
    return actingBasis({ active, self, agents: agents.map((a) => ({ agent: a.agent, kind: a.kind, ...(a.name ? { name: nameLabel(a.name) } : {}), ...(a.relationship ? { relationship: a.relationship } : {}) })), classOf: (k) => agentClassOf(k as Parameters<typeof agentClassOf>[0]), ...(delegationInHand !== undefined ? { delegationInHand } : {}) });
  }, [scope, pathname, agentAddress, agentName, personName, agents, delegationInHand]);
}

export function BasisLine({ scope, needs, delegationInHand, style }: { scope?: WorkspaceScope; /** what THIS act needs, in words (e.g. from describeRequirement) */ needs?: string; delegationInHand?: boolean; style?: React.CSSProperties }) {
  const b = useActingBasis(scope, delegationInHand);
  if (!b) return null;
  return (
    <div className="basis-line" data-testid="basis-line" data-basis={b.basis} style={{ display: 'flex', gap: '0.45rem', alignItems: 'center', flexWrap: 'wrap', fontSize: '0.72rem', opacity: 0.85, ...(style ?? {}) }} title={b.words}>
      <span>acting as <strong style={{ display: 'inline-flex', alignItems: 'center', gap: 3 }}><Icon kind={b.actingAs.kind} />{b.actingAs.name ?? short(b.actingAs.address)}</strong></span>
      {!b.same && <span>· in <strong style={{ display: 'inline-flex', alignItems: 'center', gap: 3 }}><Icon kind={b.in.kind} />{b.in.name ?? short(b.in.address)}</strong></span>}
      {!b.same && <span>· basis: <strong>{b.basis === 'stewardship' ? 'stewardship' : b.basis === 'membership' ? 'membership grant' : b.basis === 'delegation' ? 'delegation in hand' : 'none'}</strong></span>}
      {needs && <span>· this act needs <strong>{needs}</strong></span>}
    </div>
  );
}

// PRINCIPAL ≠ WORKSPACE CONTEXT, MADE VISIBLE — spec 398 §4.4. Every mutation screen and review card shows two facts
// side by side: ACTING AS (the principal SA, with its class) and IN (the workspace context). When the two differ
// ("you, in Missio Nexus") the card says on what BASIS the act may proceed: stewardship · a membership grant · a
// delegation in hand — or none. THE WORD IS STEWARDSHIP, NOT CUSTODY (agent-vocabulary.md R.2): the relation a person
// has to an organization she created is the stewardship grant it signed to her; custody is her KEY's relation to an
// address, and on a Google-custodied home that key is one she has never seen. "Custodian" belongs on Security only. A role name ("researcher") is a responsibility (344), never a basis. Pure: the words are derived
// from what the Home already knows (the managed-agent list's relationship, the workspace path); nothing here is
// authority — the verifier decides on chain, this only says what the person is standing on.
import type { WorkspaceScope } from './workspace';
import { BASIS_CAPTION } from '@agenticprimitives/ontology/participant-vocabulary';

export type AgentClass = 'person' | 'org' | 'service';
export type Basis = 'self' | 'stewardship' | 'membership' | 'delegation' | 'none';

export interface ActingBasis {
  actingAs: { address: string; name?: string; kind: AgentClass };
  in: { address: string; name?: string; kind: AgentClass };
  /** Whether the principal and the context are one and the same agent. */
  same: boolean;
  basis: Basis;
  /** The caption the switcher shows — the same words on every surface. */
  caption: string;
  /** The basis in a sentence, for the card. */
  words: string;
}

export interface KnownAgent { agent: string; name?: string; kind: string; relationship?: string }

const lc = (s: string) => s.toLowerCase();

export function actingBasis(input: {
  active: WorkspaceScope;
  self: { address: string; name?: string };
  /** The agents the Home lists for this person (stewarded and member orgs, services), with their relationship. */
  agents: ReadonlyArray<KnownAgent>;
  classOf: (kind: string) => AgentClass;
  /** A delegation in hand for the context — when a surface knows one (an org's stewardship wire, a received grant). */
  delegationInHand?: boolean;
}): ActingBasis {
  const me = { address: lc(input.self.address), ...(input.self.name ? { name: input.self.name } : {}), kind: 'person' as const };
  if (input.active.kind === 'person') {
    return { actingAs: me, in: me, same: true, basis: 'self', caption: BASIS_CAPTION.self, words: 'you, on your own agent — your key signs' };
  }
  /**
   * A PERSONA IS NOT "YOU, IN SOMETHING" — it is you under another of your names, so the PRINCIPAL is the
   * persona, not the connected person standing inside it. That is the whole difference from an org: there is
   * no second party and no grant between you and yourself, which is why the basis is `self` and `same` is
   * true. Only the NAME changes, and the name is the point — so the caption says which one, where an org's
   * says on what authority.
   */
  if (input.active.kind === 'persona') {
    const a = lc(input.active.agent);
    const row = input.agents.find((x) => lc(x.agent) === a);
    const as = { address: a, ...(row?.name ? { name: row.name } : {}), kind: 'person' as const };
    return {
      actingAs: as, in: as, same: true, basis: 'self',
      caption: BASIS_CAPTION.persona(row?.name),
      words: 'another name of yours — the same key signs, under a different name, into its own vault',
    };
  }
  const address = lc(input.active.kind === 'org' ? input.active.org : input.active.agent);
  const known = input.agents.find((a) => lc(a.agent) === address);
  const kind: AgentClass = known ? input.classOf(known.kind) : input.active.kind === 'org' ? 'org' : 'service';
  const ctx = { address, ...(known?.name ? { name: known.name } : {}), kind };
  if (known && known.relationship !== 'member') {
    return { actingAs: me, in: ctx, same: false, basis: 'stewardship', caption: BASIS_CAPTION.stewardship(ctx.name), words: 'you steward this agent — its stewardship grant names you; your key signs for it' };
  }
  if (known?.relationship === 'member') {
    return { actingAs: me, in: ctx, same: false, basis: 'membership', caption: BASIS_CAPTION.membership, words: 'a membership grant — you may take part; an act as this agent needs a steward' };
  }
  if (input.delegationInHand) {
    return { actingAs: me, in: ctx, same: false, basis: 'delegation', caption: BASIS_CAPTION.delegation, words: 'a delegation in hand — scoped to what it names, revocable on chain' };
  }
  return { actingAs: me, in: ctx, same: false, basis: 'none', caption: BASIS_CAPTION.none, words: 'no standing here — you can look, not act' };
}

'use client';
// THE ACCOUNTABLE WORK ITEM, RENDERED — spec 398 §4.3: the eight facts in one place, on every surface that shows the
// item. An absent fact is said absent ("acceptance: nobody named yet"); nothing is filled in.
import { StatePill } from '../StatePill';
import { AgentName } from '../../shared/AgentName';
import type { WorkItemV1 } from '../../../home/work-item';

function Row({ k, children }: { k: string; children: React.ReactNode }) {
  return (
    <div style={{ display: 'flex', gap: '0.5rem', alignItems: 'baseline', fontSize: '0.78rem', lineHeight: 1.5 }}>
      <span style={{ flex: 'none', width: 92, opacity: 0.6 }}>{k}</span>
      <span style={{ minWidth: 0 }}>{children}</span>
    </div>
  );
}

export function WorkItemCard({ item, org }: { item: WorkItemV1; org: string }) {
  const a = item.acceptance;
  return (
    <div data-testid="work-item" style={{ display: 'flex', flexDirection: 'column', gap: '0.1rem', marginTop: '0.5rem' }}>
      <Row k="goal">{item.goal}</Row>
      <Row k="accountable"><AgentName address={item.owner.agent as `0x${string}`} /> (organization)</Row>
      <Row k="executors">{item.executors.length === 0 ? <span style={{ opacity: 0.6 }}>nobody allocated yet</span> : item.executors.map((x, i) => <span key={x.agent}>{i > 0 ? ', ' : ''}{x.name ?? <AgentName address={x.agent as `0x${string}`} />} ({x.via}, {x.steps} step{x.steps === 1 ? '' : 's'})</span>)}</Row>
      <Row k="status"><StatePill state={item.state} native={item.native} compact /></Row>
      <Row k="conversation">{item.conversation ? <a href={`/org/${org}/discussions?topic=${encodeURIComponent(item.conversation.topicId)}`}>open the topic →</a> : <span style={{ opacity: 0.6 }}>no topic linked</span>}</Row>
      <Row k="artifacts">{item.artifacts.length === 0 ? <span style={{ opacity: 0.6 }}>none linked to this item yet — a run's artifacts are on its record (Activities)</span> : item.artifacts.map((x) => <span key={x.ref}>{x.kind} {x.ref} </span>)}</Row>
      <Row k="acceptance">
        {a.criteria.length === 0 && a.approvers.length === 0 ? <span style={{ opacity: 0.6 }}>no criteria, nobody named — a steward can revise the outcome</span> : (
          <>
            {a.criteria.length > 0 && <span>{a.criteria.join(' · ')}</span>}
            {a.approvers.length > 0 && <span>{a.criteria.length > 0 ? ' — ' : ''}decided by {a.approvers.map((p, i) => <span key={`${p.agent}:${i}`}>{i > 0 ? ', ' : ''}<AgentName address={p.agent as `0x${string}`} />{p.decisionKind ? ` (${p.decisionKind}${p.pending ? ', pending' : ''})` : p.pending ? ' (pending)' : ''}</span>)}</span>}
          </>
        )}
      </Row>
      <Row k="cost">{item.cost ? `${item.cost.vaultCalls} vault calls · ${item.cost.doRequests} serving requests` : <span style={{ opacity: 0.6 }}>not carried on the item yet — each run's bill is on its record</span>}</Row>
    </div>
  );
}

// THE ACCOUNTABLE WORK ITEM — spec 398 §4.3. One contract for one item, on every surface that shows it:
//   goal · accountable owner (a person or org SA) · executor (person or agent SA) · status (§5.1) · linked
//   conversation · output artifacts · acceptance condition and who accepts · what it cost.
// Projected from the endeavor detail (334/393) as the serving plane returns it. A field the record does not carry
// is said to be absent — never filled in from a guess: "acceptance: nobody named" is a true sentence, and the one
// that gets a steward to name an approver.
import type { WorkDetailResponse } from '../lib/work-client';
import { lifecycleState } from '../components/portal/work/labels';
import type { ProjectedRunStateV1 } from './run-state';

export interface WorkItemV1 {
  endeavorId: string;
  goal: string;
  /** Who is ACCOUNTABLE: the organization that manages the endeavor (its steward decides adoption, closure). */
  owner: { agent: string; kind: 'org' };
  /** Who does the work: every allocated participant, and those who committed (a person or an agent SA). A withdrawn or
   *  reallocated commitment is not an executor; an allocation row is the serving plane's current set. */
  executors: Array<{ agent: string; name?: string; via: 'allocation' | 'commitment'; steps: number }>;
  state: ProjectedRunStateV1;
  native: string;
  /** The context-linked topic (312), when the record names one. */
  conversation?: { topicId: string };
  /** run.artifact refs and Library versions linked to the item — none are linked by the record yet (398 gap). */
  artifacts: Array<{ ref: string; kind: string }>;
  acceptance: { criteria: string[]; approvers: Array<{ agent: string; decisionKind?: string; pending: boolean }> };
  /** 396's numbers — not yet carried by the endeavor record (harness G3); absent is absent. */
  cost: null | { vaultCalls: number; doRequests: number };
}

const lc = (s: string) => s.toLowerCase();

export function workItemOf(org: string, endeavorId: string, d: WorkDetailResponse): WorkItemV1 | null {
  const e = d.endeavor;
  if (!e) return null;
  const names = new Map((d.participations ?? []).map((p) => [lc(p.participant), p.participantName] as const));
  const executors = new Map<string, WorkItemV1['executors'][number]>();
  for (const a of d.allocations ?? []) {
    const k = lc(a.participant);
    const prev = executors.get(k);
    executors.set(k, { agent: k, ...(names.get(k) ? { name: names.get(k) } : {}), via: prev?.via === 'commitment' ? 'commitment' : 'allocation', steps: (prev?.steps ?? 0) + a.steps.length });
  }
  for (const c of d.commitments ?? []) {
    if (c.status !== 'active') continue;
    const k = lc(c.participant);
    const prev = executors.get(k);
    executors.set(k, { agent: k, ...(names.get(k) ? { name: names.get(k) } : {}), via: 'commitment', steps: Math.max(prev?.steps ?? 0, c.steps.length) });
  }
  const approvers = (d.decisions ?? []).map((x) => ({ agent: lc(x.approver), ...(x.decisionKind ? { decisionKind: x.decisionKind } : {}), pending: x.status === 'pending' }));
  return {
    endeavorId,
    goal: e.outcome?.description?.trim() || e.title,
    owner: { agent: lc(org), kind: 'org' },
    executors: [...executors.values()],
    state: lifecycleState(e.lifecycle),
    native: e.lifecycle,
    artifacts: [],
    acceptance: { criteria: e.outcome?.criteria ?? [], approvers },
    cost: null,
  };
}

/** The same contract on a LIST ROW (398 §4.3 — one item, every surface): what the row carries (goal, owner, status,
 *  progress) and what only the item carries (executors, artifacts, acceptance, cost) — said, not implied. */
export interface WorkItemRowV1 {
  goal: string;
  owner: { agent: string; kind: 'org' };
  state: ProjectedRunStateV1;
  native: string;
  progress: { satisfied: number; total: number } | null;
  /** The fields this row cannot answer — the item can. Never rendered as empty lists. */
  onItem: ReadonlyArray<'executors' | 'artifacts' | 'acceptance' | 'cost'>;
}
export function workItemRow(org: string, row: { title: string; lifecycle: string; stepsTotal?: number; stepsSatisfied?: number }): WorkItemRowV1 {
  const lc = row.lifecycle as Parameters<typeof lifecycleState>[0];
  return {
    goal: row.title, owner: { agent: org.toLowerCase(), kind: 'org' }, state: lifecycleState(lc), native: row.lifecycle,
    progress: typeof row.stepsTotal === 'number' ? { satisfied: row.stepsSatisfied ?? 0, total: row.stepsTotal } : null,
    onItem: ['executors', 'artifacts', 'acceptance', 'cost'],
  };
}

'use client';
// PAUSE · CANCEL · REVOKE · UNDO ARE FOUR THINGS — spec 398 §5.3. This is the CANCEL control for an unfinished run,
// and it says what it is not: stopping the run does not withdraw authority (that is a delegation's revocation,
// under Security — the next step would be refused, the run itself is not stopped), and it does not undo what
// already happened (an undo is a new intent with its own mandate, offered only where a compensation exists). The
// receipt of a canceled run says "stopped after step N; steps 1–N happened".
import { useState } from 'react';
import type { Address } from '@agenticprimitives/types';
import { BusyButton } from '../../shared/BusyButton';
import { cancelRun } from '../../../home/ask';

export function RunControls({ token, addressee, runRef, onCanceled, compact }: {
  token: string; addressee: Address; runRef: string;
  onCanceled?: (r: { stoppedAfter: number; happened: string[] }) => void; compact?: boolean;
}) {
  const [busy, setBusy] = useState(false);
  const [said, setSaid] = useState<string | null>(null);
  const stop = async () => {
    if (busy) return;
    const note = typeof window !== 'undefined' ? (window.prompt('Stop this run? What already happened stands. A note is kept with the record (optional).') ?? null) : '';
    if (note === null) return;
    setBusy(true);
    const r = await cancelRun({ token }, addressee, runRef, note.trim() || undefined);
    setBusy(false);
    if (!r.ok) { setSaid(r.error); return; }
    setSaid(r.stoppedAfter === 0 ? 'stopped before any step ran' : `stopped after step ${r.stoppedAfter}; step${r.stoppedAfter === 1 ? ' 1' : `s 1–${r.stoppedAfter}`} happened`);
    onCanceled?.(r);
  };
  return (
    <span style={{ display: 'inline-flex', gap: '0.5rem', alignItems: 'center', flexWrap: 'wrap' }} data-testid="run-controls" onClick={(e) => { e.stopPropagation(); e.preventDefault(); }}>
      {said
        ? <span className="ui-meta">{said}</span>
        : <BusyButton busy={busy} busyLabel="Stopping…" className={`ui-btn ui-btn--secondary${compact ? ' ui-btn--sm' : ''}`} onClick={() => void stop()} data-testid="run-cancel">Stop this run</BusyButton>}
      {!compact && !said && (
        <span className="ui-micro" title="Stopping is not withdrawing authority: to refuse the next step of any run, revoke the delegation under Security. Nothing here undoes what already happened.">
          what happened stands · <a href="/security" onClick={(e) => e.stopPropagation()}>withdraw authority</a>
        </span>
      )}
    </span>
  );
}

'use client';
// THE RUN INSPECTOR IS ARTIFACT-FIRST — spec 398 §5.2. Order, fixed: OUTCOME (how it ended, in the one vocabulary; what
// stood if it was stopped) → ARTIFACTS (391 — what the run left, by record and digest) → DECISIONS taken and pending
// (393 approvals, rule decisions, each step's authority verdict) → PLAN AND PER-STEP AUTHORITY (the plan as admitted,
// each step's verdict with the chain it read) → EXECUTION DETAIL (the spans: timings, models, routes — RunTimeline) →
// PROVENANCE (the PROV graph, downloadable). Model reasoning is not shown and is not evidence. Read from the record
// form of the run's provenance — digests, verdicts and names, never arguments or words.
import { useEffect, useState } from 'react';
import type { Address } from '@agenticprimitives/types';
import { fetchRunInspector, homeVocabulary, type AskVocabularyEntry, type RunInspectorRecord, type RunInspectorStep } from '../../../home/ask';
import { retryAffordance } from '../../../home/retry';
import { stateOf } from '../../../home/run-state';
import { StatePill } from '../StatePill';
import { RunTimeline } from './RunTimeline';
import { RunTraceTree } from './RunTraceTree';
import { TurnOperations } from './TurnOperations';
import { DisputePanel } from './DisputePanel';
import { SaveAsRecipe } from './SaveAsRecipe';
import { canSaveAsRecipe } from '@agenticprimitives/harness/recipe';
import { usePathname } from 'next/navigation';
import { parseWorkspacePath } from '../../../lib/workspace';

/** Spec 410 §2 — the four words a receipt attests, said so a stranger reads them right. */
const ATTESTS: Record<'attempted' | 'accepted' | 'committed' | 'confirmed', string> = { attempted: 'attempted — nothing came back to vouch for it', accepted: 'accepted by the provider, not yet committed', committed: 'committed by the provider', confirmed: 'confirmed — read back' };

const short = (v: unknown, n = 14): string => { const t = String(v ?? ''); return t.length > n ? `${t.slice(0, n - 4)}…${t.slice(-3)}` : t; };
const kb = (b: number): string => (b >= 1024 ? `${(b / 1024).toFixed(1)} kB` : `${b} B`);

function H({ children, n }: { children: React.ReactNode; n?: number }) {
  return <div style={{ fontWeight: 600, marginTop: '0.55rem', display: 'flex', gap: '0.4rem', alignItems: 'baseline' }}>{children}{typeof n === 'number' && <span style={{ fontWeight: 400, opacity: 0.6 }}>{n}</span>}</div>;
}

/** Spec 398 §5.3 — what stood, in words. */
export function stoppedWords(c: NonNullable<RunInspectorRecord['canceled']>): string {
  return c.afterSteps === 0 ? 'stopped before any step ran' : `stopped after step ${c.afterSteps}; step${c.afterSteps === 1 ? ' 1' : `s 1–${c.afterSteps}`} happened`;
}

export function RunInspector({ token, addressee, runRef, goal, open = true }: { token: string; addressee: Address; runRef: string; /** the ask's words, from the listing — provenance never carries them */ goal?: string; /** false ⇒ a button opens it (the Ask's How pane); nothing is fetched for a run nobody opens */ open?: boolean }) {
  const [wanted, setWanted] = useState(open);
  const [rec, setRec] = useState<RunInspectorRecord | { error: string } | null>(null);
  const [vocabulary, setVocabulary] = useState<AskVocabularyEntry[]>([]);
  const pathname = usePathname();
  useEffect(() => {
    if (!wanted) return;
    let live = true;
    void fetchRunInspector({ token }, addressee, runRef).then((r) => { if (live) setRec(r); });
    void homeVocabulary(addressee).then((v) => { if (live) setVocabulary(v); }).catch(() => undefined);
    return () => { live = false; };
  }, [token, addressee, runRef, wanted]);
  if (!wanted) return <div className="muted" style={{ marginTop: 4, fontSize: 11.5 }}><button type="button" className="btn ghost" style={{ fontSize: 10.5, padding: '0 6px', minHeight: 0 }} onClick={() => setWanted(true)}>inspect this run</button></div>;
  if (rec === null) return <div className="muted" style={{ fontSize: 11.5 }}>reading the run back…</div>;
  if ('error' in rec) return <div className="muted" style={{ fontSize: 11.5, color: 'var(--c-danger, #dc2626)' }}>{rec.error}</div>;

  const state = stateOf({ kind: 'run', outcome: rec.outcome as never, ...(rec.canceled ? { canceled: true } : {}) });
  const artifacts = rec.steps.filter((s): s is RunInspectorStep & { artifact: NonNullable<RunInspectorStep['artifact']> } => !!s.artifact);
  const approvals = rec.steps.filter((s) => s.authority?.afterApproval);
  const ruleDecisions = rec.steps.flatMap((s) => (s.decisions ?? []).map((d) => ({ step: s.stepRef, ...d })));
  const pending = rec.steps.filter((s) => s.status === 'suspended' || s.status === 'authority-required' || s.status === 'awaiting');
  const effects = rec.steps.flatMap((s) => (s.effects ?? []).map((e) => ({ step: s.stepRef, ...e })));
  const txs = rec.steps.filter((s) => s.txHash);
  // Spec 398 §7.2 (1) — the retry affordance comes from the acted capability's declared idempotency, never from a guess.
  const acted = [...rec.steps].reverse().find((s) => s.capability?.id) ?? rec.steps[rec.steps.length - 1];
  const retry = retryAffordance(state, acted?.capability?.id ?? acted?.toolId, vocabulary);

  return (
    <div className="muted" style={{ marginTop: 4, fontSize: 11.5, lineHeight: 1.55 }} data-testid="run-inspector">
      {/* 1 · OUTCOME */}
      <H>outcome <StatePill state={state} native={rec.outcome} compact /></H>
      <div>
        {rec.canceled ? <>{stoppedWords(rec.canceled)}{rec.canceled.note ? ` — “${rec.canceled.note}”` : ''} · </> : null}
        {rec.steps.length} of {rec.plannedSteps ?? rec.steps.length} planned step{(rec.plannedSteps ?? rec.steps.length) === 1 ? '' : 's'} ran
        {effects.length ? ` · ${effects.filter((e) => e.ok).length}/${effects.length} effect${effects.length === 1 ? '' : 's'} produced` : ''}
        {txs.length ? ` · on chain: ${txs.map((s) => short(s.txHash)).join(', ')}` : ''}
        {rec.playbook ? ` · playbook ${rec.playbook.skillId}@${rec.playbook.version}` : ''}
        {rec.inResponseTo ? ` · in response to ${short(rec.inResponseTo.agent, 12)} run ${short(rec.inResponseTo.runRef, 16)}` : ''}
        {rec.bill ? ` · cost: ${rec.bill.vaultCalls} vault call${rec.bill.vaultCalls === 1 ? '' : 's'}, ${rec.bill.doRequests} serving request${rec.bill.doRequests === 1 ? '' : 's'}` : ''}
      </div>
      {retry.kind !== 'none' && (
        <div data-testid="run-retry" data-retry={retry.kind} title={retry.why}>
          <a href={`/ask${goal ? `?seed=${encodeURIComponent(goal)}` : ''}`}>{retry.label} →</a> <span style={{ opacity: 0.6 }}>{retry.why}</span>
        </div>
      )}
      {/* Spec 398 §5 / APUX-034 — successful work becomes a draft recipe in the Library; a stopped or failed run does not. */}
      {canSaveAsRecipe(state, rec.outcome) && <SaveAsRecipe token={token} addressee={addressee} runRef={runRef} scope={parseWorkspacePath(pathname ?? '/')} />}

      {/* 2 · ARTIFACTS */}
      <H n={artifacts.length}>artifacts</H>
      {artifacts.length === 0
        ? <div style={{ opacity: 0.6 }}>nothing kept beyond the record (a result below the offload threshold stays in it)</div>
        : artifacts.map((s) => (
          <div key={s.stepRef} data-testid="run-artifact">
            <strong>{s.artifact.recordType}</strong> · {kb(s.artifact.bytes)} · from {s.toolId} ({s.stepRef}) · digest {short(s.artifact.digest)}
            {' '}<a href={`/library?q=${encodeURIComponent(s.artifact.recordType)}`}>in the Library →</a>
          </div>
        ))}

      {/* 3 · DECISIONS */}
      <H n={approvals.length + ruleDecisions.length + pending.length}>decisions</H>
      {approvals.length === 0 && ruleDecisions.length === 0 && pending.length === 0 && <div style={{ opacity: 0.6 }}>none were needed</div>}
      {approvals.map((s) => <div key={`a:${s.stepRef}`}>✓ approved: {s.capability?.id ?? s.toolId} ({s.stepRef}){s.authority?.presentedRef ? ` under ${short(s.authority.presentedRef)}` : ''}</div>)}
      {ruleDecisions.map((d, i) => <div key={`d:${i}`}>· {d.point} → rule {d.ruleId} ({d.step})</div>)}
      {pending.map((s) => <div key={`p:${s.stepRef}`} style={{ color: 'var(--color-amber-700, #b45309)' }}>pending: {s.capability?.id ?? s.toolId} ({s.stepRef}) — {s.status}</div>)}

      {/* 4 · PLAN AND PER-STEP AUTHORITY */}
      <H n={rec.steps.length}>plan and authority</H>
      {rec.steps.map((s) => {
        const st = stateOf({ kind: 'step', status: s.status });
        return (
          <div key={s.stepRef} style={{ display: 'flex', gap: 8, alignItems: 'baseline' }} data-testid="run-step">
            <span style={{ flex: 'none', width: 28, opacity: 0.6 }}>{s.stepRef}</span>
            <span style={{ flex: 1 }}>
              <strong>{s.capability?.id ?? s.toolId}</strong>{s.risk ? ` (${s.risk})` : ''} · <StatePill state={st} native={s.status} compact />
              {s.authority ? ` · authority ${s.authority.decision}${s.authority.presentedRef ? ` under ${short(s.authority.presentedRef)}` : ' — none presented'}${s.authority.chain ? `, chain depth ${s.authority.chain.depth} from ${short(s.authority.chain.accountabilityRoot, 12)}` : ''}${s.authority.afterApproval ? ' (after approval)' : ''}` : ' · no authority stage (informational)'}
              {s.actor?.actingAgent && s.actor.actingAgent.toLowerCase() !== rec.agent.toLowerCase() ? ` · acted by ${short(s.actor.actingAgent, 12)}` : ''}
              {s.delegatedTo ? ` · handed to ${short(s.delegatedTo, 12)}${s.delegatedToRun ? ` (run ${short(s.delegatedToRun, 16)})` : ''}` : ''}
              {s.errorClass ? ` · ${s.errorClass}` : ''}
              {/* Spec 410 §2 — the one word the receipt attests, and the provider's reference. "confirmed" alone means read back. */}
              {s.observation ? ` · ${ATTESTS[s.observation.outcome]}${s.observation.providerRef ? ` (${short(s.observation.providerRef, 18)})` : ''}` : ''}
              {s.receiptDigest ? ` · receipt ${short(s.receiptDigest)}` : ''}
            </span>
          </div>
        );
      })}

      {/* 4b · HOW IT RAN (spec 415 A3) — the run tree from the door: variant, model calls, skill selection, each step's
          skill and authority, child runs; the run's measurements on request. */}
      <H>how it ran</H>
      {/* Spec 418 §3 — the turn's operations as the record kept them (stages, selection, conversation); the model calls
          are in the tree below, each skill's under its step. A run recorded before 418 has none — said so. */}
      {rec.operational
        ? <TurnOperations testId="run-operations" stages={rec.operational.stages} selection={rec.operational.selection ?? null}
            {...(rec.operational.selectionMs !== undefined ? { selectionMs: rec.operational.selectionMs } : {})}
            {...(rec.operational.skillStage ? { skillStage: rec.operational.skillStage } : {})}
            {...(rec.operational.turn?.contextId ? { contextId: rec.operational.turn.contextId } : {})}
            {...(rec.operational.turn?.recalledTurns !== undefined ? { recalledTurns: rec.operational.turn.recalledTurns } : {})} />
        : <div style={{ opacity: 0.6 }} data-testid="run-operations-absent">operations (stages, selection): not recorded for this run</div>}
      <RunTraceTree token={token} addressee={addressee} runRef={runRef} rec={rec} />

      {/* 5 · EXECUTION DETAIL + 6 · PROVENANCE — the span timeline and its downloads */}
      <H>execution detail · provenance</H>
      <RunTimeline token={token} addressee={addressee} runRef={runRef} open />

      {/* 7 · THE DISPUTE (spec 410 §10) — whether a dispute cites this receipt, and what this person may do about it.
          The counterparty is whom the receipt names on the other side: the agent a step was routed to or acted by,
          else the run's own agent when that is not the viewer. */}
      <DisputePanel token={token} addressee={addressee} runRef={runRef} counterparty={counterpartyOf(rec, addressee)} stepRef={rec.steps.find((s) => s.authority && s.authority.decision === 'allow')?.stepRef} />
    </div>
  );
}

function counterpartyOf(rec: RunInspectorRecord, viewer: Address): Address | undefined {
  const me = viewer.toLowerCase();
  for (const s of rec.steps) {
    const other = (s.delegatedTo ?? s.actor?.actingAgent ?? '').toLowerCase();
    if (/^0x[0-9a-f]{40}$/.test(other) && other !== me) return other as Address;
  }
  return rec.agent.toLowerCase() !== me ? (rec.agent.toLowerCase() as Address) : undefined;
}

'use client';
// WHAT MY AGENT DID — spec 381 W3. One run's provenance read back from the vault as spans and drawn as a
// timeline: the run, then each step under it with what it was, how long it took, how it ended, under whose
// authority, and the hand-offs it links to. The same bytes an OTLP exporter would carry, offered as a
// download so the person can take them elsewhere. Read on demand; nothing is fetched for a run nobody opens.
import { useState } from 'react';
import type { Address } from '@agenticprimitives/types';
import { fetchSpans, fetchProvenance, type SpanRow, fetchPublicProvenance, type AnchoredOutcome, type RunAnchor, type RunAnchorCitation } from '../../../home/ask';

const ATTR = {
  step: 'ap.step.ref', status: 'ap.step.status', capability: 'ap.capability.id', risk: 'ap.risk',
  decision: 'ap.authority.verdict', presented: 'ap.authority.mandate.ref', chain: 'ap.authority.chain.depth',
  outcome: 'ap.run.outcome', origin: 'ap.trace.origin', error: 'ap.error.class', link: 'ap.link.kind',
  // Spec 390 W3 — the stage spans: which model planned or composed, and why the route put it there.
  model: 'gen_ai.request.model', provider: 'gen_ai.provider.name', route: 'ap.route.because', standing: 'ap.standing.relation', tx: 'ap.action.tx_hash',
} as const;
const short = (v: unknown, n = 14): string => { const t = String(v ?? ''); return t.length > n ? `${t.slice(0, n - 4)}…${t.slice(-3)}` : t; };
const fmtMs = (ms: number): string => (ms >= 1000 ? `${(ms / 1000).toFixed(1)}s` : `${Math.max(0, Math.round(ms))}ms`);

function attr(sp: SpanRow, key: string): string | undefined { const v = sp.attributes[key]; return v === undefined ? undefined : String(v); }

/** The run's spans as a tree: roots first, children under their parent, in start order. */
function ordered(spans: SpanRow[]): Array<{ span: SpanRow; depth: number }> {
  const byParent = new Map<string | undefined, SpanRow[]>();
  for (const sp of spans) { const k = sp.parentSpanId && spans.some((x) => x.spanId === sp.parentSpanId) ? sp.parentSpanId : undefined; byParent.set(k, [...(byParent.get(k) ?? []), sp]); }
  const out: Array<{ span: SpanRow; depth: number }> = [];
  const walk = (parent: string | undefined, depth: number) => { for (const sp of (byParent.get(parent) ?? []).sort((a, b) => a.startMs - b.startMs)) { out.push({ span: sp, depth }); walk(sp.spanId, depth + 1); } };
  walk(undefined, 0);
  return out;
}

export function RunTimeline({ token, addressee, runRef, open }: { token: string; addressee: Address; runRef: string; open?: boolean }) {
  const [state, setState] = useState<{ status: 'idle' | 'loading' | 'ready' | 'error'; spans: SpanRow[]; error?: string; exporter?: string }>({ status: 'idle', spans: [] });
  // Spec 395 — what of this run ANYONE can verify: its anchored outcomes, read from the public route (no session).
  const [anchored, setAnchored] = useState<AnchoredOutcome[] | null>(null);
  const [runAnchor, setRunAnchor] = useState<RunAnchor | null>(null);
  // Spec 410 §4.4 — an act performed in ANOTHER estate: the vault's citation says which chain anchored it.
  const [elsewhere, setElsewhere] = useState<{ citation: RunAnchorCitation; note?: string } | null>(null);
  const load = async () => {
    setState((s) => ({ ...s, status: 'loading' }));
    const out = await fetchSpans({ token }, addressee, runRef);
    if ('error' in out) setState({ status: 'error', spans: [], error: out.error });
    else setState({ status: 'ready', spans: out.spans, ...(out.exporter ? { exporter: out.exporter } : {}) });
    const pub = await fetchPublicProvenance(addressee, runRef);
    setAnchored('error' in pub ? [] : pub.rows);
    setRunAnchor('error' in pub ? null : pub.anchor ?? null);
    setElsewhere(!('error' in pub) && pub.citation && !pub.anchor ? { citation: pub.citation, ...(pub.note ? { note: pub.note } : {}) } : null);
  };
  if (open && state.status === 'idle') void load();
  const save = (text: string, name: string, type: string) => {
    const url = URL.createObjectURL(new Blob([text], { type }));
    const a = document.createElement('a'); a.href = url; a.download = name; a.click();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  };
  const download = () => save(JSON.stringify({ runRef, spans: state.spans }, null, 2), `${runRef}.spans.json`, 'application/json');
  // Spec 389 W3 — the run's PROV graph, as the vault holds it (JSON-LD) or as PROV-N: read on click, never fetched
  // for a run nobody asks about. A stock PROV tool loads either.
  const downloadProvenance = async (format: 'jsonld' | 'prov-n') => {
    const out = await fetchProvenance({ token }, addressee, runRef, format);
    if ('error' in out) { setState((s) => ({ ...s, error: out.error })); return; }
    save(out.text, format === 'jsonld' ? `${runRef}.provenance.jsonld` : `${runRef}.provenance.provn`, format === 'jsonld' ? 'application/ld+json' : 'text/provenance-notation');
  };
  const t0 = state.spans.length ? Math.min(...state.spans.map((s) => s.startMs)) : 0;
  return (
    <div className="muted" style={{ marginTop: 4, fontSize: 11.5, lineHeight: 1.55 }} data-testid="run-timeline">
      {state.status === 'idle' && <button type="button" className="btn ghost" style={{ fontSize: 10.5, padding: '0 6px', minHeight: 0 }} onClick={() => void load()}>what my agent did (spans)</button>}
      {state.status === 'loading' && <span>reading the run back…</span>}
      {state.status === 'error' && <span style={{ color: 'var(--c-danger, #dc2626)' }}>{state.error}</span>}
      {state.status === 'ready' && (
        <>
          <div>
            <strong>provenance</strong> {state.spans.length} span{state.spans.length === 1 ? '' : 's'}{state.exporter && state.exporter !== 'none' ? ` · exported via ${state.exporter}` : ''}
            {' '}<button type="button" className="btn ghost" style={{ fontSize: 10.5, padding: '0 6px', minHeight: 0 }} onClick={download}>download spans</button>
            {' '}<button type="button" className="btn ghost" style={{ fontSize: 10.5, padding: '0 6px', minHeight: 0 }} onClick={() => void downloadProvenance('jsonld')}>PROV (JSON-LD)</button>
            {' '}<button type="button" className="btn ghost" style={{ fontSize: 10.5, padding: '0 6px', minHeight: 0 }} onClick={() => void downloadProvenance('prov-n')}>PROV-N</button>
          </div>
          {runAnchor && (
            <div data-testid="run-anchor" title="The run's PROV bundle, hashed canonically (stable-key JSON, keccak256), is anchored in the ReceiptAnchorRegistry by the runtime's harness agent — bound to the intent digest. Anyone holding the bundle recomputes and reads anchorOf(digest) on the chain.">
              <strong>anchored on chain</strong> bundle {runAnchor.digest.slice(0, 14)}… · by {runAnchor.anchoredBy.slice(0, 10)}…{runAnchor.txHash ? ` · tx ${runAnchor.txHash.slice(0, 12)}…` : ''}{runAnchor.chainId ? ` · chain ${runAnchor.chainId}` : ''}
            </div>
          )}
          {elsewhere && (
            <div data-testid="run-anchor-elsewhere" title={elsewhere.note ?? 'This act was performed in another estate; its receipt is anchored on that estate\'s chain. Verify there with the digest and the anchorer the citation names.'}>
              <strong>anchored in another estate</strong>{elsewhere.citation.registry ? ` · ${elsewhere.citation.registry.startsWith('eip155:') ? `chain ${elsewhere.citation.registry.split(':')[1]}` : elsewhere.citation.registry}` : ''}{elsewhere.citation.estate ? ` · estate ${elsewhere.citation.estate.slice(0, 12)}…` : ''}{elsewhere.citation.digest ? ` · bundle ${elsewhere.citation.digest.slice(0, 14)}…` : ''}{elsewhere.citation.anchoredBy ? ` · by ${elsewhere.citation.anchoredBy.slice(0, 10)}…` : ''} — this Home reads its own estate's chain; verify at that one
            </div>
          )}
          {anchored && anchored.length > 0 && (
            <div data-testid="run-public-provenance" title="Anyone holding a receipt of this run can verify it against the agent's public projection — digests and the transaction, nothing the run was about.">
              <strong>publicly verifiable</strong> {anchored.length} anchored outcome{anchored.length === 1 ? '' : 's'}
              {anchored.map((a) => <span key={a['@id']}> · {a.capability ?? 'step'} → tx {a.anchoredBy.slice(0, 10)}…</span>)}
            </div>
          )}
          {ordered(state.spans).map(({ span: sp, depth }) => {
            const step = attr(sp, ATTR.step); const status = attr(sp, ATTR.status); const cap = attr(sp, ATTR.capability); const risk = attr(sp, ATTR.risk);
            const decision = attr(sp, ATTR.decision); const presented = attr(sp, ATTR.presented); const outcome = attr(sp, ATTR.outcome); const origin = attr(sp, ATTR.origin); const err = attr(sp, ATTR.error);
            const provider = attr(sp, ATTR.provider); const route = attr(sp, ATTR.route); const standing = attr(sp, ATTR.standing); const tx = attr(sp, ATTR.tx);
            const bad = sp.status === 'ERROR' || status === 'refused' || status === 'failed';
            return (
              <div key={sp.spanId} style={{ display: 'flex', gap: 8, paddingLeft: depth * 14, alignItems: 'baseline' }}>
                <span style={{ flex: 'none', width: 46, textAlign: 'right', opacity: 0.6 }}>+{fmtMs(sp.startMs - t0)}</span>
                <span aria-hidden style={{ flex: 'none', color: bad ? 'var(--c-danger, #dc2626)' : 'var(--c-success, #047857)' }}>{bad ? '✗' : '✓'}</span>
                <span style={{ flex: 1 }}>
                  <strong>{sp.name}</strong>{step ? ` ${step}` : ''} · {fmtMs(sp.endMs - sp.startMs)}
                  {cap ? ` · ${cap}` : ''}{risk ? ` (${risk})` : ''}
                  {status ? ` · ${status}` : outcome ? ` · ${outcome}` : ''}
                  {decision ? ` · authority ${decision}${presented ? ` under ${short(presented)}` : ''}` : ''}
                  {provider ? ` · ${provider}` : ''}{route ? ` · ${route}` : ''}{standing ? ` · standing ${standing}` : ''}{tx ? ` · tx ${short(tx)}` : ''}
                  {origin ? ` · for run ${short(origin, 18)}` : ''}
                  {err ? ` · ${err}` : ''}
                  {sp.links?.length ? ` · ${sp.links.map((l) => `${String(l.attributes?.[ATTR.link] ?? 'linked')} ${short(l.spanId)}`).join(', ')}` : ''}
                </span>
              </div>
            );
          })}
        </>
      )}
    </div>
  );
}

// THE RETRY AFFORDANCE — spec 398 §7.2 (1). A contract's `idempotency` says how many times its act may land for one
// request; a surface offers a retry ONLY where repeating is honest: `replay-safe` (a read) and `one-per-resource-version`
// (an edit) may simply be asked again; `one-per-request` (a charter, a payment, a send) is asked again as a NEW
// request, said so; an `effect-uncertain` run is never retried on a click (T10 — reconcile first). Nothing here is
// authority — the nonce the harness carries is what actually prevents a double landing.
import type { AskVocabularyEntry } from './ask';
import type { ProjectedRunStateV1 } from './run-state';

export type RetryAffordance =
  | { kind: 'retry'; label: string; why: string }
  | { kind: 'new-request'; label: string; why: string }
  | { kind: 'none'; why: string };

export function retryAffordance(state: ProjectedRunStateV1, capability: string | undefined, vocabulary: ReadonlyArray<AskVocabularyEntry>): RetryAffordance {
  if (state.effectUncertain) return { kind: 'none', why: 'the effect may have happened — reconcile before asking again' };
  if (state.state !== 'failed' && state.state !== 'canceled' && state.state !== 'expired') return { kind: 'none', why: 'the run is not over' };
  const entry = capability ? vocabulary.find((v) => v.id === capability) : undefined;
  switch (entry?.idempotency) {
    case 'replay-safe': return { kind: 'retry', label: 'Ask again', why: 'a read — repeating it is harmless' };
    case 'one-per-resource-version': return { kind: 'retry', label: 'Ask again', why: 'an edit — repeating it against an unchanged record is a no-op' };
    case 'one-per-request': return { kind: 'new-request', label: 'Ask again as a new request', why: 'this act lands once per request; a repeat is a new request with its own nonce and mandate' };
    default: return { kind: 'none', why: capability ? 'this capability declares no idempotency — no retry is offered' : 'no acted step to repeat' };
  }
}

'use client';
// ATTENTION, NOT NOTIFICATIONS — spec 398 §5.5, in the shape of an inbox (2026-09-20). What needs the person sits at
// the TOP OF THE RAIL, pinned above the conversations, in three folded groups: NEEDS YOU (decisions and questions —
// open by default), WAITING (on someone else, or a failed routine), FINISHED (artifacts). A group with nothing in it
// is not drawn; a count of zero is never shown; "unread" is a filter on the conversations, not a group beside them.
// Each card is ONE object with ONE action set — an inbox case keeps its approve/decline actions (rendered by the
// caller), a parked run its cancel, everything else opens where it is acted on. Six filters remain the MODEL
// (`attention.ts`); this is only how the screen folds them.
import { useMemo, useState } from 'react';
import type { Address } from '@agenticprimitives/types';
import { assembleAttention, attentionGroups, type AttentionGroupId, type AttentionInputs, type AttentionItem } from '../../home/attention';
import { StatePill } from './StatePill';
import { RunControls } from './runs/RunControls';
import { Button } from '../../ui';

export function AttentionGroups({ inputs, token, addressee, only, onCanceled, renderCaseActions, onOpenDm, onOpenCase }: {
  inputs: AttentionInputs; token: string; addressee: Address;
  /** Show these groups only (the "Needs you" filter shows every group, all unfolded); absent ⇒ the pinned strip. */
  only?: 'all-open';
  onCanceled: (runRef: string) => void;
  renderCaseActions: (caseId: string) => React.ReactNode; onOpenDm: (key: string) => void; onOpenCase: (caseId: string) => void;
}) {
  const groups = useMemo(() => attentionGroups(assembleAttention(inputs)), [inputs]);
  const [folded, setFolded] = useState<Partial<Record<AttentionGroupId, boolean>>>({});
  if (groups.length === 0) return null;
  return (
    <div className="chat-attention-groups" data-testid="attention-bar">
      {groups.map((g) => {
        const open = only === 'all-open' ? true : (folded[g.id] === undefined ? g.open : !folded[g.id]);
        return (
          <section key={g.id} className={`chat-attention-group chat-attention-group--${g.id}`} data-testid={`attention-${g.id}`} data-count={g.items.length}>
            <button type="button" className="chat-attention-group__head" aria-expanded={open} title={g.hint} onClick={() => setFolded((f) => ({ ...f, [g.id]: open }))} /* folded = it was open */>
              <span className="chat-attention-group__chev" aria-hidden>{open ? '▾' : '▸'}</span>
              <span className="chat-attention-group__label">{g.label}</span>
              <span className={`chat-attention-group__count${g.id === 'needs-you' ? ' chat-attention-group__count--act' : ''}`}>{g.items.length}</span>
            </button>
            {open && g.items.map((it) => <AttentionRow key={it.id} item={it} token={token} addressee={addressee} onCanceled={onCanceled} renderCaseActions={renderCaseActions} onOpenDm={onOpenDm} onOpenCase={onOpenCase} />)}
          </section>
        );
      })}
    </div>
  );
}

function AttentionRow({ item, token, addressee, onCanceled, renderCaseActions, onOpenDm, onOpenCase }: {
  item: AttentionItem; token: string; addressee: Address; onCanceled: (runRef: string) => void;
  renderCaseActions: (caseId: string) => React.ReactNode; onOpenDm: (key: string) => void; onOpenCase: (caseId: string) => void;
}) {
  const href = item.href ?? (item.askSeed ? `/ask?seed=${encodeURIComponent(item.askSeed)}` : undefined);
  const open = item.caseId ? () => onOpenCase(item.caseId!) : item.dmKey ? () => onOpenDm(item.dmKey!) : undefined;
  return (
    <div className="chat-attention-card" data-testid="attention-card">
      <div className="chat-attention-card__body">
        {href ? <a className="chat-attention-card__title" href={href}>{item.title}</a> : open ? <button type="button" className="chat-attention-card__title chat-attention-card__title--btn" onClick={open}>{item.title}</button> : <span className="chat-attention-card__title">{item.title}</span>}
        {item.detail && <div className="chat-attention-card__detail">{item.detail}</div>}
      </div>
      <div className="chat-attention-card__side">
        {item.state && <StatePill state={item.state} {...(item.native ? { native: item.native } : {})} compact />}
        {item.caseId && renderCaseActions(item.caseId)}
        {item.caseId && <Button size="sm" variant="ghost" onClick={() => onOpenCase(item.caseId!)}>Thread</Button>}
        {item.dmKey && <Button size="sm" variant="ghost" onClick={() => onOpenDm(item.dmKey!)}>Open</Button>}
        {item.runRef && <RunControls token={token} addressee={addressee} runRef={item.runRef} compact onCanceled={() => onCanceled(item.runRef!)} />}
      </div>
    </div>
  );
}

// ATTENTION, NOT NOTIFICATIONS — spec 398 §5.5 (APUX-012). The filter model on /messages: NEEDS MY DECISION · NEEDS MY
// INPUT · BLOCKED · FAILED ROUTINE · FINISHED ARTIFACT · UNREAD. An unread message is not a decision; a decision is
// not an exception; an artifact that finished is neither. One durable record per decision however it was delivered
// (393): a case in the inbox, a run parked on a signature, an allocation waiting for a commitment — each is ONE card
// with ONE action set, resolved where it is signed. Pure: it takes what the clients return and sorts it into the six;
// it fetches nothing and decides nothing about authority.
import { assembleToday, type TodayInputs, type TodayItem } from './today';

export type AttentionFilter = 'decision' | 'input' | 'blocked' | 'failed-routine' | 'artifact' | 'unread';

export const ATTENTION_FILTERS: ReadonlyArray<{ id: AttentionFilter; label: string; hint: string }> = [
  { id: 'decision', label: 'Needs my decision', hint: 'a signature, an approval you were named for, a commitment waiting on you' },
  { id: 'input', label: 'Needs my input', hint: 'your agent stopped to ask you something' },
  { id: 'blocked', label: 'Blocked', hint: 'waiting on someone else — a commitment, a steward' },
  { id: 'failed-routine', label: 'Failed routine', hint: 'a scheduled or hooked ask whose last firing failed' },
  { id: 'artifact', label: 'Finished artifact', hint: 'what recent runs left in the Library' },
  { id: 'unread', label: 'Unread', hint: 'messages you have not opened — not decisions' },
];

/** An inbox CASE as the Messages view holds it (fabric `InteractionCaseV1`, the fields this model reads). */
export interface AttentionCase { id: string; kind: string; subject: string; state: string; requester: string; responder: string; updatedAt: string; title?: string; summary?: string }
/** A direct-message bucket with its unread count (the rail's row). */
export interface AttentionDm { key: string; title: string; unread: number; lastEventAt: string; preview?: string }

export interface AttentionInputs extends TodayInputs {
  /** Cases in the inbox; those pending on ME (responder) are decisions. */
  cases: ReadonlyArray<AttentionCase>;
  /** Whose inbox this is (lowercased CAIP-10 or address) — a case I requested is not my decision. */
  me: string;
  dms: ReadonlyArray<AttentionDm>;
}

export interface AttentionItem extends TodayItem { filter: AttentionFilter; caseId?: string; dmKey?: string }

const PENDING_CASE_STATES = new Set(['submitted', 'triaged']);
const same = (a: string, b: string): boolean => a.toLowerCase().endsWith(b.toLowerCase().replace(/^.*:/, ''));

export function assembleAttention(input: AttentionInputs): Record<AttentionFilter, AttentionItem[]> {
  const today = assembleToday(input);
  const out: Record<AttentionFilter, AttentionItem[]> = { decision: [], input: [], blocked: [], 'failed-routine': [], artifact: [], unread: [] };
  // decisions: everything Today calls a decision, plus the inbox cases pending on me
  for (const d of today.decisions) out.decision.push({ ...d, filter: 'decision' });
  for (const c of input.cases) {
    if (!PENDING_CASE_STATES.has(c.state)) continue;
    if (!same(c.responder, input.me)) continue;   // I asked; someone else decides
    out.decision.push({
      id: `case:${c.id}`, title: c.title ?? c.subject, detail: c.summary ?? `${c.kind} · from ${c.requester.slice(0, 12)}…`,
      state: { state: 'awaiting-approval', effectUncertain: false }, native: c.kind, at: Date.parse(c.updatedAt), filter: 'decision', caseId: c.id,
    });
  }
  // input vs blocked: an active goal waiting on ME is input; waiting on someone else is blocked
  for (const a of today.active) {
    if (a.state?.state === 'awaiting-input') out.input.push({ ...a, filter: 'input' });
    else if (a.state?.state === 'blocked') out.blocked.push({ ...a, filter: 'blocked' });
  }
  for (const e of today.exceptions) out['failed-routine'].push({ ...e, filter: 'failed-routine' });
  for (const a of today.artifacts) out.artifact.push({ ...a, filter: 'artifact' });
  for (const dm of input.dms) {
    if (dm.unread <= 0) continue;
    out.unread.push({ id: `dm:${dm.key}`, title: dm.title, ...(dm.preview ? { detail: dm.preview } : {}), at: Date.parse(dm.lastEventAt), filter: 'unread', dmKey: dm.key });
  }
  for (const k of Object.keys(out) as AttentionFilter[]) out[k].sort((a, b) => (b.at ?? 0) - (a.at ?? 0));
  return out;
}

/** The chip counts, in the model's order. */
export function attentionCounts(a: Record<AttentionFilter, AttentionItem[]>): Array<{ id: AttentionFilter; label: string; count: number }> {
  return ATTENTION_FILTERS.map((f) => ({ id: f.id, label: f.label, count: a[f.id].length }));
}

// ─── The inbox's THREE groups (the UX of 2026-09-20) ───────────────────────────────────────────────────────────────
// Six filters is the MODEL (each a different thing); it is not the SHAPE of the screen. An inbox shows what needs
// you first, folds what is merely waiting or finished, and treats "unread" as a filter on the conversations, not as
// a bucket beside them. So the rail renders three groups from the six: NEEDS YOU (decision + input — you act, now),
// WAITING (blocked + failed routine — you wait, or you look), FINISHED (artifacts — you may look). Unread stays a
// filter. A group with nothing in it does not appear; a count of zero is never shown.
export type AttentionGroupId = 'needs-you' | 'waiting' | 'finished';
export interface AttentionGroup { id: AttentionGroupId; label: string; hint: string; items: AttentionItem[]; /** Open by default: only what needs you. */ open: boolean }

export function attentionGroups(a: Record<AttentionFilter, AttentionItem[]>): AttentionGroup[] {
  const byTime = (xs: AttentionItem[]) => [...xs].sort((x, y) => (y.at ?? 0) - (x.at ?? 0));
  const groups: AttentionGroup[] = [
    { id: 'needs-you', label: 'Needs you', hint: 'a signature, an approval, a question your agent stopped to ask', items: byTime([...a.decision, ...a.input]), open: true },
    { id: 'waiting', label: 'Waiting', hint: 'on someone else, or a routine that failed its last run', items: byTime([...a.blocked, ...a['failed-routine']]), open: false },
    { id: 'finished', label: 'Finished', hint: 'what recent runs left in the Library', items: byTime(a.artifact), open: false },
  ];
  return groups.filter((g) => g.items.length > 0);
}
/** The number that needs the person's act — the one figure an inbox may badge. */
export const needsYouCount = (a: Record<AttentionFilter, AttentionItem[]>): number => a.decision.length + a.input.length;

// TODAY — spec 398 §4.2, the outcome-led first page. Order, FIXED: decisions awaiting me → active goals → recent
// artifacts → routine exceptions → one suggested next act. Message counts and infrastructure statistics are not
// here. This module is the PURE assembly (table-tested): it takes what the clients already return — the runs parked
// on the agent (350 W3, each with its projected state), the person's work across their organizations (334/393),
// the Library's artifacts (391), the schedule (375), the vocabulary the playbook offers this realm (K5) — and
// returns the five sections. It fetches nothing and decides nothing about authority: a card here is a pointer to
// the surface where the act is signed, never the act.
import type { AskVocabularyEntry, ParkedRun, TriggerRow } from './ask';
import type { OrgWorkBundle } from '../components/portal/work/useWork';
import { stateOf, type ProjectedRunStateV1, type RunStateV1, type AwaitingKind } from './run-state';
import { lifecycleState } from '../components/portal/work/labels';

/** One card. `state` renders as the StatePill; `href` opens the surface that owns the act; `askSeed` seeds the Ask. */
export interface TodayItem {
  id: string;
  title: string;
  detail?: string;
  href?: string;
  askSeed?: string;
  state?: ProjectedRunStateV1;
  native?: string;
  at?: number;
  /** An unfinished run of the agent Today is about — the card carries its cancel control (398 §5.3). */
  runRef?: string;
}

export interface Today {
  /** Spec 398 §5.4 — what the last N days COST this agent's storage (396 numbers on the records), or null when no record carries a bill. */
  cost: { runs: number; vaultCalls: number; doRequests: number; days: number } | null;
  decisions: TodayItem[];
  active: TodayItem[];
  artifacts: TodayItem[];
  exceptions: TodayItem[];
  /** One, or none — never a list, never from a hand-kept table. */
  next: TodayItem | null;
}

export interface TodayArtifact { id: string; name: string; kind?: string; folder?: string; createdAt: number; version?: number }

export interface TodayInputs {
  now: number;
  /** The runs parked on the agent Today is about, each with the state the runtime projected (398 §5.1). */
  parked: ReadonlyArray<ParkedRun & { state?: RunStateV1 }>;
  /** The person's work across their organizations; `null` until read — Today says so rather than showing nothing. */
  bundles: ReadonlyArray<OrgWorkBundle> | null;
  artifacts: ReadonlyArray<TodayArtifact>;
  triggers: ReadonlyArray<TriggerRow>;
  vocabulary: ReadonlyArray<AskVocabularyEntry>;
  /** How far back "recent" reaches for artifacts (days). */
  recentDays?: number;
  /** The agent's run records (the listing keeps each run's bill). */
  records?: ReadonlyArray<{ at: number; bill?: { vaultCalls: number; doRequests: number } }>;
  /** Where a decision's page lives — the person's own Work, or the organization's. */
  workHref?: (org: string, endeavorId: string) => string;
}

const saOf = (caip: string): string => caip.match(/0x[0-9a-fA-F]{40}$/)?.[0]?.toLowerCase() ?? caip;
const defaultWorkHref = (org: string, endeavorId: string): string => `/org/${saOf(org)}/work/${encodeURIComponent(endeavorId)}`;

const parkedState = (r: ParkedRun & { state?: RunStateV1 }): ProjectedRunStateV1 =>
  r.state ? { state: r.state, effectUncertain: false } : stateOf({ kind: 'suspended', awaiting: r.awaiting?.kind as AwaitingKind | undefined, expired: false });

export function assembleToday(input: TodayInputs): Today {
  const workHref = input.workHref ?? defaultWorkHref;
  const recentMs = (input.recentDays ?? 7) * 86_400_000;
  const decisions: TodayItem[] = [];
  const active: TodayItem[] = [];

  // ── 1. decisions awaiting me: a parked run waiting for MY signature (382), a declared-approver decision (393),
  //       an allocation waiting for my commitment (334) ─────────────────────────────────────────────────────────
  for (const r of input.parked) {
    const st = parkedState(r);
    const item: TodayItem = {
      id: `run:${r.runRef}`, title: r.message, state: st, at: r.updatedAt, runRef: r.runRef,
      askSeed: r.message,
      ...(r.awaiting?.prompt ? { detail: r.awaiting.prompt } : {}),
      ...(r.origin?.endeavorId && r.origin.principal ? { href: workHref(r.origin.principal, r.origin.endeavorId) } : {}),
    };
    if (st.state === 'awaiting-approval') decisions.push(item);
    else if (st.state === 'expired' || st.state === 'canceled') continue;
    else active.push(item);
  }
  for (const b of input.bundles ?? []) {
    for (const c of b.decisions) {
      decisions.push({
        id: `decision:${c.decisionId}`, title: c.title,
        detail: [b.orgName, c.summary, c.dueAt ? `due ${new Date(c.dueAt).toLocaleDateString()}` : undefined].filter(Boolean).join(' · '),
        href: workHref(b.org, c.endeavorId), state: { state: 'awaiting-approval', effectUncertain: false }, native: c.decisionKind,
        at: Date.parse(c.requestedAt),
      });
    }
    for (const e of b.entries) {
      if (e.status === 'allocated') {
        decisions.push({
          id: `allocation:${e.allocationId ?? e.endeavorId}`, title: e.endeavorTitle,
          detail: [b.orgName, `${e.stepIds.length} plan step${e.stepIds.length === 1 ? '' : 's'} waiting for your commitment`, e.deadline ? `due ${new Date(e.deadline).toLocaleDateString()}` : undefined].filter(Boolean).join(' · '),
          href: '/work', state: { state: 'awaiting-approval', effectUncertain: false }, native: 'allocated', at: Date.parse(e.updatedAt),
        });
      } else {
        // ── 2. active goals: what I committed to, and the endeavor it belongs to ──
        const endeavor = b.endeavors.find((x) => x.endeavorId === e.endeavorId);
        active.push({
          id: `commitment:${e.commitmentId ?? e.endeavorId}`, title: e.endeavorTitle,
          detail: [b.orgName, `${e.stepIds.length} step${e.stepIds.length === 1 ? '' : 's'} committed`, e.deadline ? `due ${new Date(e.deadline).toLocaleDateString()}` : undefined].filter(Boolean).join(' · '),
          href: workHref(b.org, e.endeavorId),
          state: endeavor ? lifecycleState(endeavor.lifecycle) : { state: 'running', effectUncertain: false },
          ...(endeavor ? { native: endeavor.lifecycle } : {}), at: Date.parse(e.updatedAt),
        });
      }
    }
  }
  // A routine parked for a signature is a decision too (375 → 382).
  for (const t of input.triggers) {
    if (t.lastOutcome === 'parked') {
      decisions.push({
        id: `trigger-parked:${t.triggerId}`, title: t.ask, detail: 'a routine is waiting for your signature',
        href: '/playbook', state: stateOf({ kind: 'trigger', lastOutcome: 'parked' }), native: 'parked', ...(t.lastAt ? { at: t.lastAt } : {}),
      });
    }
  }
  decisions.sort((a, b) => (b.at ?? 0) - (a.at ?? 0));
  active.sort((a, b) => (b.at ?? 0) - (a.at ?? 0));

  // ── 3. recent artifacts (391 run.artifact, Library releases) — newest first, the last N days ──
  const artifacts: TodayItem[] = input.artifacts
    .filter((a) => a.createdAt >= input.now - recentMs && a.createdAt <= input.now + 60_000)
    .sort((a, b) => b.createdAt - a.createdAt)
    .slice(0, 6)
    .map((a) => ({
      id: `artifact:${a.id}`, title: a.name,
      detail: [a.kind, a.version && a.version > 1 ? `v${a.version}` : undefined, a.folder ? `in ${a.folder}` : undefined].filter(Boolean).join(' · '),
      href: `/library?open=${encodeURIComponent(a.id)}`, at: a.createdAt,
    }));

  // ── 4. routine exceptions: a firing that failed (paused triggers are shown when the schedule carries pause) ──
  const exceptions: TodayItem[] = input.triggers
    .filter((t) => t.lastOutcome === 'failed')
    .map((t) => ({
      id: `trigger:${t.triggerId}`, title: t.ask, detail: t.lastSaid ? t.lastSaid.slice(0, 160) : 'the last firing failed',
      href: '/playbook', state: stateOf({ kind: 'trigger', lastOutcome: 'failed' }), native: 'failed', ...(t.lastAt ? { at: t.lastAt } : {}),
    }))
    .sort((a, b) => (b.at ?? 0) - (a.at ?? 0));

  // ── 5. one suggested next act — from the vocabulary the playbook offers THIS realm (K5-narrowed), never a hand
  //       list: the lowest-risk act with a label, that nothing above is already about; deterministic by id ──
  const busy = new Set(input.parked.map((r) => r.message.toLowerCase()));
  const rank = (t: string): number => ({ informational: 0, low: 1, medium: 2, high: 3, critical: 4 } as Record<string, number>)[t] ?? 5;
  const candidate = [...input.vocabulary]
    .filter((v) => (v.label ?? '').trim() && !busy.has((v.label ?? '').toLowerCase()))
    .sort((a, b) => rank(a.riskTier) - rank(b.riskTier) || a.id.localeCompare(b.id))[0];
  const next: TodayItem | null = candidate
    ? { id: `next:${candidate.id}`, title: candidate.label ?? candidate.id, ...(candidate.description || candidate.resultKind ? { detail: [candidate.description, candidate.resultKind ? `→ a ${candidate.resultKind}` : undefined].filter(Boolean).join(' · ') } : {}), askSeed: candidate.label ?? candidate.id, native: candidate.id }
    : null;

  // ── cost (§5.4): the bills on the records of the last N days — shown on Today because the record carries them (harness G3).
  const billed = (input.records ?? []).filter((r) => r.at >= input.now - recentMs && r.bill);
  const cost = billed.length
    ? { runs: billed.length, vaultCalls: billed.reduce((n, r) => n + (r.bill?.vaultCalls ?? 0), 0), doRequests: billed.reduce((n, r) => n + (r.bill?.doRequests ?? 0), 0), days: input.recentDays ?? 7 }
    : null;

  return { cost, decisions, active, artifacts, exceptions, next };
}

// Slack-style rail timestamp: a time today, the weekday within the last week, else the long date.
const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
const DAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];

function ordinal(n: number): string {
  const s = ['th', 'st', 'nd', 'rd'];
  const v = n % 100;
  return `${n}${s[(v - 20) % 10] ?? s[v] ?? s[0]}`;
}

export function railDate(iso: string, now: Date = new Date()): string {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return '';
  const startOfToday = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  const startOfThat = new Date(d.getFullYear(), d.getMonth(), d.getDate());
  const dayDiff = Math.round((startOfToday.getTime() - startOfThat.getTime()) / 86_400_000);
  if (dayDiff <= 0) return d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  if (dayDiff === 1) return 'Yesterday';
  if (dayDiff < 7) return DAYS[d.getDay()]!;
  return `${MONTHS[d.getMonth()]} ${ordinal(d.getDate())}, ${d.getFullYear()}`;
}

/** The section a conversation belongs to in an inbox rail — Today · Yesterday · This week · Earlier. */
export type RailGroup = 'Today' | 'Yesterday' | 'This week' | 'Earlier';
export function railGroup(iso: string, now: Date = new Date()): RailGroup {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return 'Earlier';
  const startOfToday = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  const startOfThat = new Date(d.getFullYear(), d.getMonth(), d.getDate());
  const dayDiff = Math.round((startOfToday.getTime() - startOfThat.getTime()) / 86_400_000);
  if (dayDiff <= 0) return 'Today';
  if (dayDiff === 1) return 'Yesterday';
  if (dayDiff < 7) return 'This week';
  return 'Earlier';
}

'use client';
// M06 — THE FLEET BOUNDARY, SHOWN — spec 398 §4.4: for each managed agent, three lines and not an avatar: WHERE IT
// RUNS (this deployment's runtime, its own serving object), WHAT IT MAY SPEND (the grants in force on it — its wires,
// 329), WHAT IT HOLDS (its own vault, whether its key is bound). Read from the same endpoints the planes and the
// vault-key ceremony use; absent is said absent.
import { useEffect, useState } from 'react';
import type { Address } from '@agenticprimitives/types';
import { postA2a } from '../../home/ask';
import { A2A_DOMAIN, VAULT_SERVER_ID } from '../../lib/domain';

interface Facts {
  planes: { interactions: boolean | null; delivery: boolean | null; current: boolean | null };
  vault: { bound: boolean | null; resources: number };
}

export function FleetLines({ agent, token, stewardship }: { agent: Address; token: string; /** the steward's wire — one of what it may spend */ stewardship?: boolean }) {
  const [f, setF] = useState<Facts | null>(null);
  useEffect(() => {
    let live = true;
    void (async () => {
      const st = (await postA2a(`/a2a/interactions/${agent.toLowerCase()}/status`, { session: token }).catch(() => ({}))) as { granted?: boolean; current?: boolean; deliveryGranted?: boolean };
      const kb = (await fetch(`/mcp-bind/custody/vault-key/is-bound?owner=${agent.toLowerCase()}`).then((r) => r.json()).catch(() => ({}))) as { bound?: boolean; allowedResources?: string[] };
      if (!live) return;
      setF({
        planes: { interactions: st.granted ?? null, delivery: st.deliveryGranted ?? null, current: st.current ?? null },
        vault: { bound: kb.bound ?? null, resources: kb.allowedResources?.length ?? 0 },
      });
    })();
    return () => { live = false; };
  }, [agent, token]);
  const spends = f
    ? [stewardship ? 'your stewardship wire' : null, f.planes.interactions ? `interactions plane${f.planes.current === false ? ' (stale — re-enable)' : ''}` : null, f.planes.delivery ? 'delivery plane' : null].filter(Boolean)
    : [];
  return (
    <div className="fleet-lines" data-testid="fleet-lines" style={{ fontSize: '0.72rem', opacity: 0.8, display: 'flex', flexDirection: 'column', gap: 1, marginTop: '0.3rem' }}>
      <div><span style={{ opacity: 0.6 }}>runs at</span> {A2A_DOMAIN} · its own serving object</div>
      <div><span style={{ opacity: 0.6 }}>may spend</span> {f === null ? '…' : spends.length ? spends.join(' · ') : 'nothing granted yet'}</div>
      <div><span style={{ opacity: 0.6 }}>holds</span> {f === null ? '…' : f.vault.bound ? `its own vault at ${VAULT_SERVER_ID} · key bound (${f.vault.resources} scope${f.vault.resources === 1 ? '' : 's'})` : 'no vault key bound yet'}</div>
    </div>
  );
}

'use client';
// MEMBERS — who is in this organization and how to reach them (design system v2, 2026-09-13). A ROSTER: one row per
// member with their mark, their name and public name, what kind of participant they are, the responsibility they
// carry, and what they may read here — searchable, filterable by kind; a row opens the member's contract (spec 398
// §4.5: type · sponsor · responsibility · permissions · active work) in a drawer, and hands them to the Ask as its
// selection (361 I6). Managing membership is Settings → Membership; this is the participation view.
//
// A WORKSPACE'S MEMBERS ARE ITS GOVERNOR'S (the owner's rule, 2026-10-02; `org.ttl` §2): a `.workspace` agent is a
// service that coordinates a workspace and holds no members; who belongs is the organization that governs it. So
// for a workspace this page resolves the governor — the viewer's own link to the workspace names it as `parent`,
// and a steward with the workspace's wire can read the `workspace.governor` pointer out of its vault — and reads
// the roster THERE, saying so in one line. A workspace with no governor (paired before the rule) reads its own.
import { useCallback, useEffect, useMemo, useState } from 'react';
import { useSession } from '../../context/session';
import { SectionShell } from './SectionShell';
import { fetchWorkspaceRoster, workspaceGovernorOf, type RosterMember } from '../../lib/recipient-directory';
import { useManagedAgents } from './ManagedAgents';
import { vaultReadWithDelegation } from '../../lib/vault-client';
import type { DelegationWire } from '../../lib/delegation';
import { nameLabel } from '../../lib/domain';
import { AddressChip } from '../shared/AddressChip';
import { setAskSelection } from '../../home/ask-selection';
import { rosterRows, type RosterRow } from '../../home/roster-contract';
import { fetchWorkList } from '../../lib/work-client';
import { List, Row, KeyValue, ErrorNote, LinkButton, Panel, Stats, Stat, SearchInput, FilterChip, Avatar, Chip, Drawer, Button, type PanelState } from '../../ui';
import { InboxIcon } from './today-icons';

type KindFilter = 'all' | 'person' | 'agent';
// agent-vocabulary.md §1: the two kinds a roster holds beside people are SERVICES (a runtime, a coach, a treasury) and
// organizations (a team); the filter's word is Services — never "agents", which every member is.
const isAgentType = (t: string) => t === 'service' || t === 'organization';
const typeWords = (t: string) => (t === 'unknown' ? 'member' : t.replace(/[_-]+/g, ' '));

export function MemberRoster({ agent, title = 'Members' }: { agent: string; title?: string }) {
  const { session, agentAddress } = useSession();
  // 'any': the roster of a deactivated org still opens from its URL (spec 342), and the governor of a workspace
  // must be findable whatever its lifecycle row says.
  const { agents: managed, loaded: managedLoaded } = useManagedAgents(session?.token ?? null, 'any');
  const [members, setMembers] = useState<RosterMember[] | null>(null);
  /** Whose records the roster is: the governing organization (address + name), or null for an organization's own
   *  page and for a legacy workspace reading its own. */
  const [heldBy, setHeldBy] = useState<{ agent: string; name: string } | null>(null);
  const [executors, setExecutors] = useState<Map<string, number>>(new Map());
  const [error, setError] = useState<string | null>(null);
  const [selected, setSelected] = useState<string | null>(null);
  const [q, setQ] = useState('');
  const [kind, setKind] = useState<KindFilter>('all');

  const row = managed.find((a) => a.agent.toLowerCase() === agent.toLowerCase());
  const load = useCallback(async () => {
    if (!session?.token || !managedLoaded) return;
    setError(null);
    try {
      // THE GOVERNOR, cheapest door first: the viewer's own link (`parent`, no request); then, for a steward holding
      // the workspace's wire, the pointer in the workspace's vault — the vault read this app already makes for an
      // agent the person stewards. A member without the wire and without a parent link reads the workspace itself.
      let governor = workspaceGovernorOf(row, managed);
      if (!governor && row?.kind === 'workspace' && row.stewardshipDelegation) {
        const ptr = await vaultReadWithDelegation<{ governedBy?: string }>(row.stewardshipDelegation as DelegationWire, 'workspace.governor').catch(() => null);
        const g = String(ptr?.governedBy ?? '').toLowerCase();
        governor = /^0x[0-9a-f]{40}$/.test(g) && g !== agent.toLowerCase() ? g : null;
      }
      const roster = await fetchWorkspaceRoster(session.token, agent, row?.kind === 'workspace' ? governor : null);
      setMembers(roster.members);
      const gov = roster.governedBy ? managed.find((a) => a.agent.toLowerCase() === roster.governedBy) : undefined;
      setHeldBy(roster.governedBy ? { agent: roster.governedBy, name: gov?.name ? nameLabel(gov.name) : `${roster.governedBy.slice(0, 6)}…${roster.governedBy.slice(-4)}` } : null);
      const w = await fetchWorkList(session.token, agent).catch(() => null);
      const counts = new Map<string, number>();
      const me = (agentAddress ?? '').toLowerCase();
      if (me) counts.set(me, (w?.mine?.allocations?.length ?? 0) + (w?.mine?.commitments ?? []).filter((c) => c.status === 'active').length);
      setExecutors(counts);
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e));
      setMembers([]);
    }
  }, [session?.token, agent, agentAddress, managedLoaded, row, managed]);
  useEffect(() => { void load(); }, [load]);

  const rows = useMemo(() => (members ? rosterRows({ members, executors }) : []), [members, executors]);
  const agents = rows.filter((m) => isAgentType(m.type)).length;
  const stewards = rows.filter((m) => /steward|custodian|founder/i.test(`${m.role ?? ''} ${m.responsibility ?? ''}`)).length;
  const needle = q.trim().toLowerCase();
  const shown = rows.filter((m) => (kind === 'all' || (kind === 'agent') === isAgentType(m.type)) && (!needle || `${m.displayName} ${m.publicName ?? ''} ${m.role ?? ''} ${m.responsibility ?? ''} ${m.address}`.toLowerCase().includes(needle)));
  const open = selected ? rows.find((m) => m.address.toLowerCase() === selected) ?? null : null;
  const state: PanelState = members === null ? 'loading' : shown.length ? 'ready' : 'empty';

  if (!session) return <SectionShell title={title}><Panel title={title} state="empty" empty={{ title: 'Not signed in' }} /></SectionShell>;

  const pick = (m: RosterRow) => {
    const next = selected === m.address.toLowerCase() ? null : m.address.toLowerCase();
    setSelected(next);
    setAskSelection(next ? { entity: next as `0x${string}`, kind: 'person', label: m.displayName } : null);
  };

  return (
    <SectionShell title={title} description={<>The people and services in this workspace and how to reach them. Who belongs is decided under Settings → Membership.</>}>
      {error && <ErrorNote>{error}</ErrorNote>}
      {heldBy && (
        // The line that says WHOSE records these are: a workspace agent coordinates and holds no members; the
        // organization governing it does. A link, because that is where membership is managed.
        <p className="ui-note" data-testid="roster-held-by">
          Membership is held by <a href={`/org/${heldBy.agent}/members`}>{heldBy.name}</a> (this workspace&apos;s organization).
        </p>
      )}
      <Stats>
        <Stat label="Members" value={rows.length} loading={members === null} hint="people and services admitted" />
        <Stat label="Services" value={agents} loading={members === null} hint="runtimes, coaches, treasuries" />
        <Stat label="Stewards" value={stewards} loading={members === null} hint="who may act for the organization" />
      </Stats>
      <div className="ui-toolbar">
        <SearchInput placeholder="Search members…" value={q} onChange={(e) => setQ(e.target.value)} aria-label="Search members" />
        <div style={{ display: 'flex', gap: 6 }}>
          <FilterChip active={kind === 'all'} onClick={() => setKind('all')}>All</FilterChip>
          <FilterChip active={kind === 'person'} count={members ? rows.length - agents : undefined} onClick={() => setKind('person')}>People</FilterChip>
          <FilterChip active={kind === 'agent'} count={members ? agents : undefined} onClick={() => setKind('agent')}>Services</FilterChip>
        </div>
        {/* Spec 400 W1b — the Members-panel shortcut: pair your own runtime (Claude Code, goose) as a member of this
            workspace. The ceremony lives on your Contacts → Your runtimes; this is the door from where the roster is. */}
        <LinkButton size="sm" href="/contacts#runtimes" title="Pair your own Claude Code or goose as a member — a code from your Home, your signatures">Add a runtime</LinkButton>
      </div>
      <Panel title="Roster" icon={<InboxIcon />} count={shown.length} state={state} rows={5} lead testId="roster"
        empty={{ title: needle || kind !== 'all' ? 'No member matches' : 'No members yet', hint: needle || kind !== 'all' ? 'Clear the search or the filter.' : 'Invite someone under Settings → Membership; they appear here once they accept.' }}>
        <List>
          {shown.map((m) => {
            const you = !!agentAddress && m.address.toLowerCase() === agentAddress.toLowerCase();
            const picked = selected === m.address.toLowerCase();
            const isAgent = isAgentType(m.type);
            return (
              <div key={m.address} className="ui-row" role="button" tabIndex={0} aria-pressed={picked} data-testid={`member-${m.address}`}
                onClick={() => pick(m)} onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); pick(m); } }}
                style={{ cursor: 'pointer', ...(picked ? { background: 'var(--st-accent-bg)', boxShadow: 'inset 3px 0 0 var(--color-action)' } : {}) }}>
                <div className="ui-row-lead"><Avatar name={m.publicName ?? m.displayName} address={m.address} agent={isAgent} /></div>
                <div className="ui-row-main">
                  <div className="ui-row-title" style={{ display: 'flex', gap: 'var(--sp-2)', alignItems: 'baseline', flexWrap: 'wrap' }}>
                    {m.displayName}{you && <Chip>you</Chip>}
                    {m.publicName && <span className="ui-meta">{m.publicName}</span>}
                  </div>
                  <div className="ui-row-meta" data-testid={`member-facets-${m.address}`}>
                    {typeWords(m.type)}{m.responsibility ? ` · ${m.responsibility}` : ''}{m.kin ? ` · ${m.kin}` : ''}{m.role && m.role !== 'member' ? ` · ${m.role}` : ''} · {m.permissions.length > 60 ? `${m.permissions.slice(0, 57)}…` : m.permissions}
                  </div>
                </div>
                <div className="ui-row-side">
                  {isAgent && <Chip>agent</Chip>}
                  {you && m.activeWork > 0 && <Chip tone="ok">{m.activeWork} active</Chip>}
                  {!you && <LinkButton size="sm" href={`/messages?to=${m.address}`} onClick={(e) => e.stopPropagation()}>Message</LinkButton>}
                </div>
              </div>
            );
          })}
        </List>
      </Panel>
      {open && (
        <Drawer title={<span style={{ display: 'inline-flex', gap: 10, alignItems: 'center' }}><Avatar name={open.publicName ?? open.displayName} address={open.address} agent={isAgentType(open.type)} size="sm" />{open.displayName}</span>} onClose={() => { setSelected(null); setAskSelection(null); }}
          actions={!(agentAddress && open.address.toLowerCase() === agentAddress.toLowerCase()) ? <LinkButton size="sm" variant="primary" href={`/messages?to=${open.address}`}>Message</LinkButton> : undefined}>
          <div style={{ marginBottom: 'var(--sp-4)' }}><AddressChip address={open.address as `0x${string}`} size="sm" /></div>
          {/* Spec 398 §4.5 — the roster contract: type · sponsor · responsibility · permissions · active work. */}
          <div className="ui-card ui-card--quiet" data-testid={`member-contract-${open.address}`}>
            <KeyValue rows={[
              ['Type', typeWords(open.type), { absent: open.type === 'unknown' }],
              ['Public name', open.publicName ?? 'none', { absent: !open.publicName }],
              ['Sponsor', open.sponsor],
              ['Responsibility', open.responsibility ?? 'none assigned', { absent: !open.responsibility }],
              ['Permissions', open.permissions],
              ['Active work', agentAddress && open.address.toLowerCase() === agentAddress.toLowerCase() ? (open.activeWork === 0 ? 'none' : `${open.activeWork} item${open.activeWork === 1 ? '' : 's'}`) : 'not visible to you — their own view', { absent: !(agentAddress && open.address.toLowerCase() === agentAddress.toLowerCase()) }],
            ]} />
          </div>
          <p className="ui-note" style={{ marginTop: 'var(--sp-4)' }}>Selected for the Ask: a command from this page names this member. <Button size="sm" variant="ghost" onClick={() => { setSelected(null); setAskSelection(null); }}>Clear</Button></p>
        </Drawer>
      )}
    </SectionShell>
  );
}

// THE ROSTER, PER PARTICIPANT — spec 398 §4.5: type · sponsor (who admitted them and under what situation, 324) ·
// responsibility (344 — never a basis) · permissions summary (their grants, plain words) · active work (items where
// they are executor). Projected from the two views of membership the roster already unions (a member's own listing,
// the steward's received-grant index) and the organization's work list. Pure; absent is said absent.
import { VAULT_RECORD_SCOPE_ENFORCER, decodeVaultRecordScopeTerms } from '@agenticprimitives/delegation';
import type { Hex } from '@agenticprimitives/types';
import type { RosterMember } from '../lib/recipient-directory';

export type ParticipantType = 'person' | 'organization' | 'service' | 'unknown';

export interface RosterRow extends RosterMember {
  type: ParticipantType;
  /** Who admitted them and how: their own signed listing, or the organization's grant on an invitation. */
  sponsor: string;
  /** A responsibility (344) — a role name or a household relation; never a basis for authority. */
  responsibility?: string;
  permissions: string;
  /** Items where this member is an executor (allocated or committed). */
  activeWork: number;
}

export interface RosterInputs {
  members: ReadonlyArray<RosterMember & { admittedVia?: 'listing' | 'invite'; grantCaveats?: Array<{ enforcer: string; terms: string }> }>;
  /** Participants with an allocation or an active commitment, by lowercased address, from the work list. */
  executors: ReadonlyMap<string, number>;
  orgName?: string;
}

const SUFFIX: Record<string, ParticipantType> = {
  me: 'person', impact: 'person', agent: 'person',
  org: 'organization', team: 'organization', church: 'organization', circle: 'organization', household: 'organization',
  svc: 'service', treasury: 'service', workspace: 'service', registry: 'service',
};

export function participantType(publicName: string | null): ParticipantType {
  if (!publicName) return 'unknown';
  const tld = publicName.split('.').pop()?.toLowerCase() ?? '';
  return SUFFIX[tld] ?? 'unknown';
}

/** A record resource in words: `vault:member.profile:0x3b99…` → "the member profile for this organization";
 *  `vault:message.body:*` → "message bodies". An address qualifier names the organization, never the hex. */
function resourceWords(resource: string): string {
  const [key, ...rest] = resource.replace(/^vault:/, '').replace(/:\*$/, '').split(':');
  const label = (key ?? '').replace(/[._-]+/g, ' ');
  if (!rest.length) return label;
  if (/^0x[0-9a-fA-F]{40}$/.test(rest[0] ?? '')) return `the ${label} for this organization`;
  return `${label} ${rest.join(':')}`;
}

/** The record scopes a grant carries, in plain words ("read the organization's profile"). */
export function permissionWords(caveats: ReadonlyArray<{ enforcer: string; terms: string }> | undefined): string {
  if (!caveats?.length) return 'a membership grant — take part; no record scope named';
  const scope = caveats.find((c) => c.enforcer.toLowerCase() === VAULT_RECORD_SCOPE_ENFORCER.toLowerCase());
  if (!scope) return 'a membership grant — take part; no record scope named';
  try {
    const grants = decodeVaultRecordScopeTerms(scope.terms as Hex);
    const words = grants.flatMap((g) => g.resources.map((r) => `${g.ops.join('/')} ${resourceWords(r)}`));
    return words.length ? words.join(' · ') : 'a membership grant — take part';
  } catch { return 'a membership grant (scope unreadable here)'; }
}

export function rosterRows(i: RosterInputs): RosterRow[] {
  return i.members.map((m) => {
    const type = participantType(m.publicName);
    const sponsor = m.admittedVia === 'invite'
      ? `admitted by ${i.orgName ?? 'the organization'} on an invitation (its steward signed the grant)`
      : m.admittedVia === 'listing' ? 'published their own signed listing here' : 'membership recorded; how they were admitted is not in either view';
    const responsibility = [m.kin, m.role && m.role !== 'member' ? m.role : undefined].filter(Boolean).join(' · ') || undefined;
    return {
      ...m, type, sponsor, ...(responsibility ? { responsibility } : {}),
      permissions: m.admittedVia === 'invite' ? permissionWords(m.grantCaveats) : 'their own listing — what they published about themselves; acts still need a mandate',
      activeWork: i.executors.get(m.address.toLowerCase()) ?? 0,
    };
  });
}

'use client';
// SAVE AS RECIPE — spec 398 §5 / APUX-034 (G3). On a COMPLETED run only: the runtime drafts a SKILL.md from the record
// and the playbook (steps, capabilities, parties as roles; no key can reach it — the keyring is not an input), the
// person reads what it holds, and SAVES it into the workspace's Library under recipes/. The saved file says, in its own
// words, that assigning it grants nothing. Two steps, each said: draft (a read) → save (the person's act).
import { useState } from 'react';
import type { Address } from '@agenticprimitives/types';
import { draftRecipeOf, type RecipeDraft } from '../../../home/ask';
import { recipeSaveTarget, recipeSummary } from '../../../home/recipe';
import { BusyButton } from '../../shared/BusyButton';
import type { WorkspaceScope } from '../../../lib/workspace';

export function SaveAsRecipe({ token, addressee, runRef, scope }: { token: string; addressee: Address; runRef: string; scope: WorkspaceScope }) {
  const [draft, setDraft] = useState<RecipeDraft | null>(null);
  const [busy, setBusy] = useState<'draft' | 'save' | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [saved, setSaved] = useState<{ href: string; name: string } | null>(null);

  const doDraft = async () => {
    setBusy('draft'); setErr(null);
    const out = await draftRecipeOf({ token }, addressee, runRef);
    setBusy(null);
    if (!out.ok) { setErr(out.error); return; }
    setDraft(out.recipe);
  };
  const doSave = async () => {
    if (!draft) return;
    setBusy('save'); setErr(null);
    const target = recipeSaveTarget(draft, scope);
    try {
      const r = await fetch(`/connect/library${target.scopeQuery}`, { method: 'POST', headers: { authorization: `Bearer ${token}`, 'content-type': 'application/json' }, body: JSON.stringify({ action: 'save', ...(target.scopeQuery ? { org: target.scopeQuery.slice('?org='.length) } : {}), artifact: target.artifact }) });
      const b = (await r.json().catch(() => ({}))) as { ok?: boolean; error?: string; artifact?: { id: string; name: string } };
      if (!r.ok || !b.ok) throw new Error(b.error ?? `the Library answered ${r.status}`);
      setSaved({ href: `${target.libraryHref}&open=${encodeURIComponent(b.artifact?.id ?? '')}`, name: b.artifact?.name ?? target.artifact.name });
    } catch (e) { setErr(e instanceof Error ? e.message : String(e)); }
    setBusy(null);
  };

  if (saved) return <div data-testid="recipe-saved">saved to the Library as <a href={saved.href}><code>{saved.name}</code></a> — a draft; assigning it asks for authority anew</div>;
  return (
    <div data-testid="save-as-recipe" style={{ display: 'flex', flexDirection: 'column', gap: '0.25rem' }}>
      <div style={{ display: 'flex', gap: '0.5rem', alignItems: 'center', flexWrap: 'wrap' }}>
        {!draft && <BusyButton busy={busy === 'draft'} busyLabel="Drafting…" className="btn-ghost" style={{ width: 'auto', fontSize: '0.72rem' }} onClick={() => void doDraft()} title="A draft SKILL.md from this run's plan: steps, capabilities, parties as roles. No key, no mandate can reach it." data-testid="recipe-draft">Save as recipe…</BusyButton>}
        {draft && <>
          <span><code>{draft.fileName}</code> · {recipeSummary(draft)}</span>
          <BusyButton busy={busy === 'save'} busyLabel="Saving…" className="btn-primary" style={{ width: 'auto', fontSize: '0.72rem' }} onClick={() => void doSave()} data-testid="recipe-save">Save to the Library</BusyButton>
          <button type="button" className="btn-ghost" style={{ fontSize: '0.72rem' }} onClick={() => setDraft(null)}>Discard</button>
        </>}
      </div>
      {draft && draft.notes.length > 0 && <div style={{ opacity: 0.7 }}>not carried: {draft.notes.join(' · ')}</div>}
      {draft && <details><summary style={{ cursor: 'pointer' }}>the draft</summary><pre style={{ fontSize: 10.5, whiteSpace: 'pre-wrap', maxHeight: 260, overflow: 'auto', margin: '0.25rem 0' }} data-testid="recipe-text">{draft.skillMd}</pre></details>}
      {err && <div style={{ color: 'var(--color-danger)' }}>{err}</div>}
    </div>
  );
}

// SAVE AS RECIPE — spec 398 §5 / APUX-034 (G3), the Home half. The runtime drafts (from the record and the playbook, never
// a key); the person SAVES, into the Library of the workspace the run belonged to, as a `skill` artifact (a SKILL.md
// package, ADR-0051) under `recipes/`. The Library entry is a Library artifact like any other: versioned, shareable,
// publishable (398 §6.2) — and assigning it to an agent asks for authority anew, which the draft itself says.
import type { RecipeDraft } from './ask';

export interface RecipeSaveTarget {
  /** `/connect/library` scope: the org's Library when the run was an organization's, else the person's own. */
  scopeQuery: string;
  folder: 'recipes';
  artifact: { name: string; kind: 'skill'; source: 'blob'; folder: 'recipes'; contentType: 'text/markdown'; bytesB64: string };
  /** Where the saved artifact opens. */
  libraryHref: string;
}

const b64 = (s: string): string => (typeof btoa === 'function' ? btoa(unescape(encodeURIComponent(s))) : Buffer.from(s, 'utf8').toString('base64'));

/** Where and as what the draft is saved — pure, so the target is testable without a Library. */
export function recipeSaveTarget(recipe: Pick<RecipeDraft, 'fileName' | 'skillMd'>, scope: { kind: 'person' } | { kind: 'persona'; agent: string } | { kind: 'org'; org: string } | { kind: 'service'; agent: string }): RecipeSaveTarget {
  // The Library is keyed by the AGENT the run belonged to, whatever class it is — only the href differs,
  // because each class serves its Library under its own workspace prefix.
  const org = scope.kind === 'org' ? scope.org.toLowerCase() : scope.kind === 'service' || scope.kind === 'persona' ? scope.agent.toLowerCase() : null;
  return {
    scopeQuery: org ? `?org=${org}` : '',
    folder: 'recipes',
    artifact: { name: recipe.fileName, kind: 'skill', source: 'blob', folder: 'recipes', contentType: 'text/markdown', bytesB64: b64(recipe.skillMd) },
    libraryHref: `${org ? (scope.kind === 'org' ? `/org/${org}/library` : scope.kind === 'persona' ? `/as/${org}/library` : `/service/${org}/library`) : '/library'}?folder=recipes`,
  };
}

/** The sentence the affordance shows before saving: what the draft holds and what it does not. */
export function recipeSummary(r: RecipeDraft): string {
  const roles = r.roles.length ? `${r.roles.length} role${r.roles.length === 1 ? '' : 's'} (${r.roles.map((x) => `{${x.role}}`).join(', ')})` : 'no roles';
  return `${r.steps.length} step${r.steps.length === 1 ? '' : 's'} · ${r.capabilities.length} capabilit${r.capabilities.length === 1 ? 'y' : 'ies'} · ${roles} · no keys, no mandates — authority is asked for anew when it is assigned`;
}

// ARTIFACT IDENTITY — spec 398 §6.2 (APUX-038). Every artifact shows: exact version · author (an SA) · sources · scope
// (which vault, which grants) · linked work item · access method — one of the four the review names: OWNED LOCALLY ·
// LIVE REMOTE · AUTHORIZED REPLICA · DERIVED COPY (mapped from the Library's access mode and source; 338 publications,
// 316 delivery tiers). Share, publish and replicate are three distinct acts: sharing a preview never grants vault or
// sandbox access. Pure; absent is said absent.
export type AccessMethod = 'owned locally' | 'live remote' | 'authorized replica' | 'derived copy';

export interface ArtifactLike {
  id: string; name: string; version?: number; source: 'blob' | 'graphdb' | 'vault' | 'external'; pointer?: string; discussionId?: string;
  contentCommitment?: string; createdAt: number; grants?: Array<{ grantee: { address: string; label?: string }; revoked?: boolean }>; effectiveGrants?: unknown[];
  /** The registry edition this copy was written from (the server's `registry`), beside the vault's own save count. */
  registry?: { id: string; version: string | number };
  releases?: Array<{ version: string; publisher: string; publishedAt: number }>; accessMode?: 'Owned' | 'Read-through' | 'Replica' | 'Public' | 'Projection'; sharedBy?: string;
}

export interface ArtifactIdentity {
  version: string;
  /** The SA that authored it — the vault's owner for an owned artifact; the sharer for a shared one. */
  author: string;
  sources: Array<{ kind: 'pointer' | 'topic' | 'commitment' | 'registry'; value: string }>;
  /** The registry edition this copy was written from, beside the vault's own save count. */
  registryEdition?: { id: string; version: string };
  scope: { vault: string; grants: number; live: number };
  /** No artifact carries its work item yet (398 §4.3) — said absent. */
  linkedWorkItem: null;
  accessMethod: AccessMethod;
  /** The three acts, each with whether THIS surface offers it. */
  acts: { share: 'offered' | 'not-owner'; publish: 'offered' | 'not-publishable' | 'not-owner'; replicate: 'not-yet' };
  latestRelease?: { version: string; publisher: string; at: number };
}

export function accessMethodOf(a: Pick<ArtifactLike, 'source' | 'accessMode'>): AccessMethod {
  const mode = a.accessMode ?? 'Owned';
  if (mode === 'Replica') return 'authorized replica';
  if (mode === 'Public' || mode === 'Projection') return 'derived copy';
  if (mode === 'Read-through') return 'live remote';
  return a.source === 'external' ? 'live remote' : 'owned locally';
}

export function artifactIdentity(a: ArtifactLike, owner: { sa: string; vaultLabel: string }, publishable: boolean): ArtifactIdentity {
  const owned = (a.accessMode ?? 'Owned') === 'Owned';
  const grants = a.grants ?? [];
  const latest = [...(a.releases ?? [])].sort((x, y) => y.publishedAt - x.publishedAt)[0];
  return {
    version: `v${a.version ?? 1}`,
    author: owned ? owner.sa : (a.sharedBy ?? owner.sa),
    sources: [
      ...(a.pointer ? [{ kind: 'pointer' as const, value: a.pointer }] : []),
      ...(a.discussionId ? [{ kind: 'topic' as const, value: a.discussionId }] : []),
      ...(a.contentCommitment ? [{ kind: 'commitment' as const, value: a.contentCommitment }] : []),
      ...(a.registry ? [{ kind: 'registry' as const, value: `${a.registry.id} v${a.registry.version}` }] : []),
    ],
    ...(a.registry ? { registryEdition: { id: a.registry.id, version: String(a.registry.version) } } : {}),
    scope: { vault: owner.vaultLabel, grants: grants.length, live: grants.filter((g) => !g.revoked).length },
    linkedWorkItem: null,
    accessMethod: accessMethodOf(a),
    acts: { share: owned ? 'offered' : 'not-owner', publish: !owned ? 'not-owner' : publishable ? 'offered' : 'not-publishable', replicate: 'not-yet' },
    ...(latest ? { latestRelease: { version: latest.version, publisher: latest.publisher, at: latest.publishedAt } } : {}),
  };
}
